UPDATE locales_page_text SET Text_loc1 = '<HTML><BODY><H1 align = \"center\"> 호르데 임원 지대 </H1><BR/><P align = \"center\"> 제 2 부 </P><IMG src = \"Interface  PvPRankBadges  PvPRank09 \"align =\"left \"/><BR/><P align =\"right \"> 백부장 </P><BR/><BR/><IMG src =\"Interface  PvPRankBadges  PvPRank08 \"align =\"left \" <BR/><BR/><BR/><P align = \"left\"/><BR/><BR/><BR/><P align = \"right\"> 병역 거부 <BR/><BR/><BR/><IMG src = \"인터페이스  PvPRankBadges  PvPRank07\" <BR/><BR/><IMG src = \"Interface  PvPRankBadges  PvPRank06\"align = \"left\"/><BR/><P align = \"right\"> 블러드 가드 </P> > 스톤 가드 </BODY><BR/><BR/><BR/></BODY></HTML>' WHERE entry = 2854;
UPDATE locales_page_text SET Text_loc1 = '오늘은 새로운 퓨마 흔적을 쫓아 남쪽으로 사냥을 나갔다. 출발한 지 얼마되지 않아 우리는 밧줄로 만들어진 멋진 다리가 놓인 계곡에 이르렀다. 기술이 낳은 이 경이로운 다리를 보는 순간 나는 이 지역을 묘사한 브란의 글을 떠올리지 않을 수 없었다. 종종 트롤 원주민은 원시적이고 교육 받지 못한 종족이라 생각했지만, 뛰어난 기술로 만들어진 다리를 올려다 보면서 나는 이 불가능해 보이는 일을 이뤄낸 트롤 건축가들의 솜씨를 인정하게 되었다.' WHERE entry = 108;
UPDATE locales_page_text SET Text_loc1 = '우리는 해가 뜨자마자 트카시 폐허를 지나 남쪽을 향해 출발했다. 바닐은 붉은머리부족과 마주치게 되지 않을까 걱정했다. 나는 바닐에게 붉은머리부족은 그들 일족의 숙적인 백골가루부족을 처치하는 데 여념이 없을 거라고 상기시켜 주었다. 물론 바닐은 전혀 안심하지 않았지만, 나는 장전된 총, 화약을 가득 담은 가방, 그리고 세 명의 뛰어난 사냥꾼이 있어 어떤 적이 습격해 온다 해도 걱정이 없었다.' WHERE entry = 114;
UPDATE locales_page_text SET Text_loc1 = '아제크와 얼가딘 경은 균형을 잡고 서서 흔들리는 나무 밑에서 털을 곤두세우고 있는 거대한 놈에게 총을 겨누었다. 한낮의 태양은 따갑게 내리쬐고 있었다. 핀을 뒤로 당기는 얼가딘의 관자놀이에서 땀 한 방울이 천천히 흘러내렸다. 방아쇠를 당기는 소리와 함께 두꺼운 식물이 갈라지고 너무나도 아름다운 거대한 검은 표범이 곧 평원 위에 쓰러졌다.' WHERE entry = 110;
UPDATE locales_page_text SET Text_loc1 = '가시덤불 골짜기의 푸른 언덕 - 첫째 날은 보통 그렇듯이 순조롭게 지나갔다. 우리는 기지 구축을 위해 필요한 준비를 하는 데 대부분의 시간을 보냈다. 나는 담수가 흘러드는 강어귀 가에서 이상적인 장소를 찾아냈다. 근처에 낡고 버려진 부두가 있는 걸로 보아 이곳은 예전에 어떤 종족이 거주하던 곳인 것 같다. 그러나 원래 누가 살던 땅이었는지는 시간이 흘러야만 알 수 있을 것이다.' WHERE entry = 95;
UPDATE locales_page_text SET Text_loc1 = '하이 엘프들이 트롤들의 격렬한 맹공격에 맞서 싸우면서 로데론의 유목민 인 흩어진 사람들은 자신의 종족 지역을 통합하기 위해 싸웠습니다.초기 인류의 부족들은 인종 통일 또는 명예에 대해 거의주의하지 않고 서로의 정착촌을 급습했습니다.' WHERE entry = 1865;
UPDATE locales_page_text SET Text_loc1 = '엘프들은 토라 딘에게 트롤 군대가 광대했고 트롤들이 켈 탈라스를 파괴했으면 남부 지방을 공격 할 것이라고 전했습니다. 절망적 인 엘프들은 군사 원조를 절실히 필요로하며, 급히 전쟁에 맞서 도움을 줄 특정 마법을 휘두르는 사람을 가르치기로 서둘러 동의했다.' WHERE entry = 1870;
UPDATE locales_page_text SET Text_loc1 = '엘프들은 인간이 자연스럽게 마법을 다루는 데 서투르지 만 자연스럽고 자연 스럽다는 것을 알게되었습니다. 100 명의 사람들이 엘프의 마법의 비밀에 대해 아주 기본적인 것을 배웠습니다. 트롤과 싸우기 위해서는 절대적으로 필요한 것만 큼 없었습니다. 그들의 인간 학생이 투쟁을 돕기 위해 준비가되었음을 확신하고, 엘프는 스톰을 떠나 북부 왕 토라 딘 군대와 함께 북쪽으로 여행했습니다.' WHERE entry = 1872;
UPDATE locales_page_text SET Text_loc1 = '100 명의 인간 마법사와 수많은 엘프 마법사가 하늘의 분노를 불러 트롤 군대를 불 태웠다. 원소 화재로 트롤들이 상처를 재생하지 못하게하고 고문 된 형태를 안쪽에서 태워 버렸습니다.' WHERE entry = 1874;
UPDATE locales_page_text SET Text_loc1 = '진질에게<br /> 이미 오랜 시간이 흘렀지만 붉은깃털일족의 마지막 생존자가 죽었다는 사실을 알고 싶어할 것 같군. 이 편지를 자네에게 전하는 사람이 한 일이니 내게 감사할 필요는 없네. 자네가 원한다면 불모의 땅에서 짐마차의 순회가 끝나는 대로 그녀의 머리를 자네에게 보내 주겠네. 자네의 부두 마법을 사용하기 위해서는 그게 필요하다는 사실을 알고 있으니 말이야.<br />잘 지내게, 내 오랜 벗이여<br /><br /> -달소크 스위프트대거' WHERE entry = 415;
UPDATE locales_page_text SET Text_loc1 = '친애하는 마르텍,<br /><br />나는 지금 곤경에 빠져 자네 도움이 필요하다네. 우리 형제가 경주용 자동차를 제작하고 있는데 튼튼한 피스톤이 필요하네. 여러 가지를 시도해 봤지만 그 어느 것도 강도가 충분치 못하더군. 우리가 만든 새 자동차의 속도를 견뎌 낼 수 있는 게 하나도 없어. 그래서 계속 엔진 고장을 일으키고 있네!<br /><br />자네가 금속 가공에는 전문가이니 꼭 도와주기 바라네. 자네만이 할 수 있는 일일세.$B다음은 피스톤의 사양입니다.<br /><br />길이: 32 WW<br />너비: 12WW<br />무게: 23.5 IBG~25.5 IBG<br />전도율: 70 TC<br />전단력: 98 이상<br />결합 강도: \'엄청 튼튼\' 이상<br />노움의 측정 단위를 잊으셨다면 다음을 참고하세요.<br />WW = \'수염 너비\'<br />IBG = \'아주 조금\' 그램<br />TC = \'발가락 털 길이\'' WHERE entry = 441;
UPDATE locales_page_text SET Text_loc1 = '승리는 그들의 것이지만, 필멸의 인종은 전쟁으로 산산조각이 난 세계에서 발견되었습니다. 스컬지와 불타는 군단은 로데론의 문명을 모두 파괴했지만 칼림도어에서 거의 일을 마쳤습니다.치유 할 숲과 묻기 위해 원한이 있었고 고향이 정착했습니다. 전쟁은 각 종족을 심하게 다치게했지만, 그들은 얼라이언스와 호드 사이의 불안한 휴전으로 시작하여 새로운 무언가를 시도하기 위해 무의식적으로 결속했다.' WHERE entry = 2104;
UPDATE locales_page_text SET Text_loc1 = '이 증명서를 소지 한 사람은 일급 성직자와 도둑이받을 자격이 있다고 존중하고 존중할 자격이 있습니다.' WHERE entry = 992;
UPDATE locales_page_text SET Text_loc1 = '&lt;페이지마다 고대 엘프의 룬문자가 가득합니다.&gt;<br /><br />본 서적은 하급 영약을 제조하는 데 필요한 재료를 수집하고 제작하는 과정에서 일어난 사건들에 대한 기억을 담고 있다.<br /><br />부디 이 책이 적들의 손에 들어가지 않기를.<br /><br />부디 살아서 다시 한번 쿠엘탈라스에 창백한 달빛이 비치는 광경을 볼 수 있기를.<br /><br />부디 캘타스님의 은총 속에서 숨을 거두기를.<br /><br />부디 일리단님의 영광을 위해 살생도 불사하기를.<br /><br />-카리엘 윈탈루스$B<img src=\\$B />$B<img src=\\$B />$B<img src=\\$B />$B<img src=\\$B />' WHERE entry = 1633;
UPDATE locales_page_text SET Text_loc1 = '고대 시대에 타이탄이 아제로스를 떠난 후, 토성으로 알려진 그들의 아이들은 계속해서 세계의 깊은 함몰을 형성하고 보호했습니다. 토양은 표면 거주 인종의 일에 크게 관심이 없었으며 지구의 어두운 깊이를 연결하기를 간절히 원했습니다.' WHERE entry = 1892;
UPDATE locales_page_text SET Text_loc1 = '드워프들을 불러내 어, 마지막 토기는 울다 만의 홀을 떠나 깨어나는 세계로 나섰다. 아직도 깊은 곳의 안전과 경이로움에 시달리면서, 그들은 땅의 가장 높은 산 밑에 광대 한 왕국을 세웠습니다.' WHERE entry = 1895;
UPDATE locales_page_text SET Text_loc1 = '드워프는 본질적으로 보석과 돌을 형성하는 것에 매료되어 주변 산들을 재물과 소중한 무기물로 채굴하기 시작했습니다. 드워프들은 세계에서 그들의 노동에 대한 만족감을 가지고 표면에 거주하는 이웃들의 일에서 고립되어있었습니다.' WHERE entry = 1897;
UPDATE locales_page_text SET Text_loc1 = '메디브가 아제로스에서 태어난 무렵, 킬제덴은 사기꾼의 자리에서 그의 추종자들 사이에 앉았습니다. 그의 주인 인 살게라스의 명령에 따라 교활한 악마 군주는 불타는 군단의 두 번째 아제로스 침공을 계획하고있었습니다.' WHERE entry = 1942;
UPDATE locales_page_text SET Text_loc1 = '두 종족 중 킬재덴은 전사 오크가 레기온의 부패에 더 취약하다는 것을 알았습니다. 그는 살게라스가 옛날에 아즈샤라 여왕을 장악 한 것과 같은 방식으로 노인 오크 샤먼 인 넬 줄을 사로 잡았습니다. 교활한 무당을 자신의 도관으로 사용하여 악마는 오크 씨족 전체에 전투의 욕망과야만을 퍼트렸다.' WHERE entry = 1946;
UPDATE locales_page_text SET Text_loc1 = '킬 재덴은 오크들에 대한 억지력을 강화하기 위해 굴 \'단이 암흑 군주를 조작하고 드라 노스 전역에 워록 마술을 퍼뜨리는 비밀 교단 인\'그림자 당회 \'를 찾도록 도왔습니다. 점점 더 많은 오크들이 마술을 휘두르기 시작하면서, 드레 노어의 부드러운 들판과 물줄기가 검게되고 퇴색하기 시작했습니다. 시간이 지남에 따라 오크들이 광대 한 대초원을 만들어 세대를 거쳐 사라지 자마자 붉은 색 불모지 만 남았습니다. 악마 에너지가 서서히 세상을 죽였습니다.' WHERE entry = 1950;
UPDATE locales_page_text SET Text_loc1 = '그들의 사나운 사촌들의 퇴장으로 나이트 엘프들은 그들의 매혹적인 고국의 보관을 다시 그들의 관심으로 돌 렸습니다. 드루이드들은 자신의 동면 시간이 가까워지고, 잠들 준비가되어 있고, 사랑하는 가족과 가족들을 남겨두고 떠났다.' WHERE entry = 1849;
UPDATE locales_page_text SET Text_loc1 = '삶의 모든 것들과 마찬가지로, 슬픈 이야기에 비극, 혼돈, 그리고 악의 영광스럽고 은색의 안감이 있습니다. 당신이 저를 죽인 동안, 당신은 그렇게 느리고 무질서한 방식으로 그렇게했습니다. 나는이 세상을 구원하는 유일한 희망을 파괴 한 후에이 서신을 쓸 시간이 충분했습니다. 분쇄 한 붉은 결정 가루는 왕권의 조각으로 남겨져 있습니다.$B$B' WHERE entry = 2839;
UPDATE locales_page_text SET Text_loc1 = '<이 페이지들을 보니 엄청난 고통을 느낍니다.>' WHERE entry = 2653;
UPDATE locales_page_text SET Text_loc1 = '이 2 차 대전에서 남은 자들은 호드가 아이언 포지 마운틴을 정복하기 위해 얼마나 위험스럽게 닫혔는지에 대한 자극적 인 알림으로 작용합니다.' WHERE entry = 1771;
UPDATE locales_page_text SET Text_loc1 = '작전이 시작되었소.<br /><br />한때 위대한 신앙의 보루였던 수호영웅의 안식처를 기지로 삼고 상황이 정리되면 전갈을 보내 주시오. 그러면 서부 몰락지대에서 우리가 지원군을 보내 주리다.<br /><br />그 지역은 스톰윈드의 주민들과 병사들에게 잊혀진 곳이나 다름없어 우리가 공격 발판으로 삼기에는 더없이 좋은 곳이 될 것이오. 데피아즈단은 스톰윈드를 되찾게 될 것이오!<br /><br />당신의 답신을 기다리겠소.' WHERE entry = 811;
UPDATE locales_page_text SET Text_loc1 = '요르겐,<br />내가 두려워하던 일이 현실로 드러났네. 그것도 내가 전혀 생각지도 못했던 방식으로 말일세. 놈들이 이렇게 가까이 다가올 줄은 생각도 못했었네.<br />이 편지를 전하는 이를 도와주도록 하고 그를 \'그\'에게 보내게. 솔직히 말해, 내 생각에는 이번 일이 워낙 심각한 만큼 그가 우릴 도와줄 것 같네. 만약 다른 위협이었다면 그가 우리와 우리 도시의 문제를 계속 무시해 버리겠지만 말이야. 고맙네, 이 어부 친구야. 언제나 자네에게 신세만 지는구먼.<br />자네의 친구, 드라베이' WHERE entry = 528;
UPDATE locales_page_text SET Text_loc1 = '&lt;페이지마다 고대 엘프의 룬문자가 가득합니다.&gt;<br /><br />본 서적은 하급 영약을 제조하는 데 필요한 재료를 수집하고 제작하는 과정에서 일어난 사건들에 대한 기억을 담고 있다.<br /><br />부디 이 책이 적들의 손에 들어가지 않기를.<br /><br />부디 살아서 다시 한번 쿠엘탈라스에 창백한 달빛이 비치는 광경을 볼 수 있기를.<br /><br />부디 캘타스님의 은총 속에서 숨을 거두기를.<br /><br />부디 일리단님의 영광을 위해 살생도 불사하기를.<br /><br />-카리엘 윈탈루스$B<img src=\\$B />$B<img src=\\$B />$B<img src=\\$B />' WHERE entry = 1632;
UPDATE locales_page_text SET Text_loc1 = '절벽파수꾼 롱혼에게 보내는 긴급 전갈<br /><br />에톡 야영지의 켄타우로스 군대가 대규모로 공격하여 보급품 짐마차 중 한 대를 습격. 짐마차에 타고 있던 자들과 보급품 실종 및 분실. 지금까지의 켄타우로스 공격과는 달리 매우 과감한 공격으로, 앞으로 추가 공격이 우려됨.' WHERE entry = 1711;
UPDATE locales_page_text SET Text_loc1 = '안녕하세요, 펠노크!<br /><br />불타는 평원에서 진행 중인 연구는 놀라운 진척을 보이고 있어요. &lt;name&gt;님 덕분에 가능한 일이었죠! 연구를 계속하려면 필요한 게 있습니다.<br />강철코일 범버비첼 1개<br />17게이지 얼음 스패너 1개<br />오리 깃털 5Kg<br />당신이 만든 풀 1단지<br />다음에 또 보게 되면 당신 장화에 석탄 넣으면 안 된다는 거 잊어 버리지 않게 꼭 얘기해 주세요! 고마워요, 펠노크<br /><br />- 팅키' WHERE entry = 1691;
UPDATE locales_page_text SET Text_loc1 = '--첫째 날--<br /><br />마침내 아이언포지에서 칼림도어로 왔다. 바엘 모단의 발굴조사단장 카즈고름의 일은 상당한 진척을 보이고 있다. 그는 오늘 고고학자들이 고대 신의 뼈 조각이라 생각하는 화석을 발견했다. 카즈고름은 그 화석이 더 큰 신비의 일부라고 확신하고 있다. 발굴 현장을 감독하는 동안 그는 내게 더 많은 화석 조각을 찾으라고 지시했다. 내 임무는 남쪽으로 가서 더 많은 단서를 찾는 것이다.$B--둘째 날--<br /><br />불모의 땅은 넓고 광활하다. 내 여행은 길고 힘들었으나 지금까지 탐험가 연맹의 기록에 남길 만한 성과는 아무 것도 얻지 못했다.<br /><br />그나마 발굴 단장의 관심을 끌 만한 유일한 사건이 황금길 근처에서 일어났다. 먼 곳에서 괴상하게 생긴 생물이 다가오고 있는 것이었다. 반은 돼지, 반은 사람의 모습을 하고 있었다. 나는 재빨리 숨어 그 역겨운 괴물이 지나가길 기다렸다. 괴물이 지나간 자리엔 악취가 진동했다.$B--셋째 날--<br /><br />아, 정말 위대하고 멋진 발견이다!<br /><br />오늘 괴상한 것을 발견했다. 엄청난 크기의 멧돼지 같이 생긴 동물의 유해였다. 그 해골은 내 키의 몇 배 높이로 솟아 있었다. 이 짐승의 이빨 하나하나의 크기는 드워프만 했다. 아니, 드워프보다도 클 정도였다. 이것만 보더라도 말로만 듣던 고대 신들 중 하나의 시체가 분명한 것 같다.$B얼마 전 아이언포지 탐험가 연맹 본부에서 열렸던 수석고고학자 그레이위스커의 강연이 기억난다. 까탈스럽기로 유명한 그 노인은 다르나서스에 있는 이상한 엘프들의 숭배를 받는 신에 대해 언급했었다.<br /><br />흠, 잠깐! 텐트 밖에서 콧바람 소리가 들린다. 엉겅퀴멧돼지가 내가 숨겨둔 사과를 노리고 있는 게 분명하다.$B--넷째 날--<br /><br />붙잡혔다!<br /><br />어서... 서둘러... 기록을 남겨야 한다.<br /><br />돼지 인간 가시덩굴일족에게 공격 당했다. 나는 놈들이 타락한 멧돼지 신의 거대한 화석으로 데려가고 있다고 생각했다. 하지만 그들은 그 거대한 화석을 지나 황금길을 가로질러 서쪽으로 곧장 나아갔다.$B나는 가시덩굴 우리라고 하는 역겨운 냄새가 나는 가시덤불 속으로 거칠게 내동댕이쳐졌다. 조악하게 만들어진 오두막 안에는 그들에게 잡힌 나이트 엘프가 죽어가고 있었다.<br /><br />이 일지와... 내 깃털 달린 펜, 그리고 내 회중시계 외에 모든 소지품을 빼앗겼다.<br /><br />지금 누군가 오고 있다...$B--다섯째 날--<br /><br />나와 함께 갇힌 나이트 엘프는 심각한 부상으로 고통받고 있다. 돼지 인간들이 그에게 계속 채찍질을 했다. 기적이 일어나 어느 용감한 구조대가 이 위험한 곳에 들어와 우릴 구해 주지 않는 한, 그는 곧 죽음을 맞이할 것이다. 의식이 오락가락하고 있는 모양이다. 그가 깨어나면 내 몫으로 남겨 뒀던 물을 줘야겠다.$B지난 밤 그는 처음으로 말문을 열 수 있었다. 자신을 드루이드 헤랄라스라고 소개하며 이 타락한 멧돼지 신에 대한 소문을 조사하기 위해 이곳으로 파견됐다고 했다.<br /><br />그는 힘겨운 목소리로 10,000여 년 전 고대의 전쟁 중 거대한 멧돼지 신 아감마간이 불타는 군단과의 전투에서 최후를 맞이했던 곳에 그 거대한 멧돼지의 해골이 있을 것이라고 말했다. 그의 육중한 몸 때문에 땅이 평평해졌고 그의 피는 땅속으로 스며들었다. 그의 피가 떨어진 곳에는 소용돌이치는 가시가 자랐다고 한다.$B헤랄라스와 그의 일족들은 이곳에서 타락의 원인을 찾고 있다고 했다. 그가 말하기로는, 아감마간은 순수한 신이라 숭상되었다고 한다. 그런데 왜 이 생물로부터 나온 가시가 이 땅을 해치고 있는 것인지 참으로 알 수 없는 일이다.<br /><br />내가 더 자세한 정보를 묻기도 전에 헤랄라스는 또 다시 의식을 잃고 말았다.$B--여섯째 날--<br /><br />헤랄라스의 상태가 악화되고 있다.<br /><br />오늘은 눈을 한번 밖에 뜨지 않았다. 고통을 억누르며 한 그의 말은 분명했다. 만약 이 가시덩굴 우리에서 탈출하게 된다면 탈라나르에 있는 팔핀델 웨이워더에게 서슬깃 차를가가 불모의 땅 남부에서 부하들을 일으키고 있다는 걸 알려야 한다. 녀석들의 세력은 날로 커가고 있다. 가시덩굴 우리에서 타락의 역병이 퍼져나가기 전에 차를가를 막아야 한다.$B불쌍한 헤랄라스... 얼굴이 백짓장처럼 창백하다. 한시가 다르게 열이 높아지고 있다. 한편 돼지 인간들은 대규모의 군사 행동을 준비하느라 바쁜 나날을 보내고 있다. 어서 탈출을 시도하지 않으면 나도 이 친구와 같은 운명을 맞게 될까 봐 두렵다.<br /><br />내 계획은 돼지 인간들이 다음 번 사냥을 떠날 때 몰래 빠져 나가는 것이다. 다행히 나를 감시하는 경비병은 게을러서 근무를 서는 동안 졸고 있을 때가 많다.$B우리에서 빠져나와 버섯구름 봉우리로 간 다음 페랄라스라는 신비한 숲의 경계에 있는 탈라나르를 향해 서쪽으로 갈 것이다. 그곳에서 팔핀델 웨이워더라는 드루이드를 찾아볼 것이다.<br /><br />우리 종족의 역사를 조사하기 위해 시작했던 일이 이제 생각보다 훨씬 더 큰일이 돼버렸다. 얼라이언스의 안전이 이제 내 손에 달렸다.' WHERE entry = 424;
UPDATE locales_page_text SET Text_loc1 = '사령관,<br /><br />오그리마로 귀환하라. 귀관의 부대로는 부족하니 새로운 정보를 기초로 우리의 상황을 재분석해야 한다.<br /><br />다수의 어둠의 혈맹과 오우거들이 있으며 어둠의 문은 악마들이 감시하고 있다.<br /><br />- 호드 대족장, 스랄' WHERE entry = 1071;
UPDATE locales_page_text SET Text_loc1 = '바엘 모단 발굴<br /><br />애초에 탐험가 연맹에서 파견한 조사단이 발견했던 내용이 옳았다. 이곳 땅에는 우리 종족에게 무한한 가치를 갖는 유물들이 묻혀 있다. 바엘 모단의 모래와 바위 아래에서 지식을 구한다면 틀림없이 많은 해답을 얻게 될 것이다.<br /><br />하지만 이 지역의 지질학적 특성 때문에 극단적인 수단을 사용해야 한다. 혹독한 조건과 변화하는 기후로 인해 많은 모래 더미가 단단하게 굳어 버린 것이다.$B그러나 해결 방법은 매우 간단하다. 나무 펄프를 흡수제로 사용하면 미량의 니트로글리세린을 질산나트륨과 섞어 강력한 폭발물을 만들 수 있는데, 이렇게 하면 아무리 밀도 높은 덩어리라도 뚫을 수 있다.<br /><br />시끄럽고 파괴적인 작업이 되겠지만 인근 주민들의 안락함보다는 우리의 조사가 훨씬 더 중요하다. 사실, 벌써 이 주변에서 알짱대며 성가시게 굴던 황소 인간 무리를 몰아낼 수밖에 없었다.$B이곳에는 다양한 악당들이 돌아다니고 있어 이에 대처하려면 왕국 군대의 지원이 필요할 것 같다. 발굴 작업에만 군사 지원이 필요한 것이 아니라 이곳에 온 지 얼마 안 된 내가 보기에 현재 폭발 직전인 세계 정치 상황을 감안할 때 바엘 모단은 위치상 얼라이언스에 전략적 가치가 있을 것으로 보인다.<br /><br />이런, 주제에서 벗어난 이야기를 하고 말았다. 바위 밑에서 해야 할 일이 잔뜩 있는데도 글 쓰는 데 너무 많은 시간을 보내느라 발굴을 충분히 하지 못했다...' WHERE entry = 342;
UPDATE locales_page_text SET Text_loc1 = '그러나 솔루션은 매우 간단합니다. 목재 펄프를 흡착제로 사용하여 니트로 글리세린의 흔적을 질산 나트륨과 결합하여 강력한 폭발력을 발휘할 수 있으며 가장 밀도가 높은 질량까지도 파괴 할 수 있습니다.$B$B작업은 시끄럽고 파괴적 일 수 있지만 우리의 탐색은 훨씬 더 큽니다 지역 주민의 안락함보다 중요합니다. 사실, 우리는 이미 불쾌한 것으로 판명 된 지역에서 황소 무리를 몰아 내야했습니다.' WHERE entry = 343;
UPDATE locales_page_text SET Text_loc1 = '죽음의추적자 임무 보고<br /><br />대원: 레인 요릭, 쿠인 요릭, 엘런드 맥크리<br /><br />주요 임무: 은빛소나무 숲 북부 지역 조사 및 야생 동물과 스컬지의 위협 수준 파악.$B대원들이 정찰을 개시하여 상당수의 늑대가 존재함을 확인했습니다. 사냥 부대를 파견하여 이 위협을 누그러뜨리는 것이 좋겠습니다.<br /><br />죽음의 농장이라고 부르는 지역에서 언데드 놀들이 발견되었습니다. 그들이 농장에 나타난 목적이 무엇인지는 알아내지 못했지만, 그들의 움직임과 준비 상황으로 보아 군사 행동이 임박했음을 알 수 있었습니다. 놀들이 목격된 당시 그들 중 중요한 지도자는 눈에 띄지 않았습니다. 지휘부 또는 증원군이 도착하기를 기다리고 있는 것 같습니다.$B정찰을 계속하던 우리 대원들은 이바르의 호박밭에 고립돼 있습니다. 이바르와 그의 가족 및 일꾼들 중 대부분은 스컬지에 굴복하여 그들의 앞잡이가 되었습니다.<br /><br />우리 대원들은 공격을 받았지만 그들의 매복 부대를 물리치는 데 성공했습니다. 그러나 큰 타격을 받았으며, 특히 쿠인 대원의 부상이 심각합니다.$B이바르의 낡은 집에 방어선을 마련하고 레인이 적의 추가 공격에 대비해 망을 보는 동안 엘런드가 정찰 임무를 계속 수행했습니다.<br /><br />그러다 엘런드가 북쪽 과수원에서 검은늑대들에게 포위를 당했고 다른 포세이큰 대원의 도움으로 겨우 탈출할 수 있었습니다. 이 보고서를 전하는 전령이 바로 그 대원입니다.$B이 보고서를 전달하는 이는 우리의 임무 완수에 도움이 되었을 뿐만 아니라 포악한 이바르를 물리치고, 엘런드를 구조하며, 이 보고서를 무사히 전달하는 등의 공훈이 있음을 인지해 주시기 바랍니다.<br /><br />우리는 그에게 감사를 전하며, 이 자에게 전장에서 보여 준 영웅적 행위에 합당한 보상을 지급할 것을 건의합니다.<br /><br />- 죽음의추적자 레인 요릭<br />작전 대장' WHERE entry = 380;
UPDATE locales_page_text SET Text_loc1 = '&lt;페이지마다 고대 엘프의 룬문자가 가득합니다.&gt;<br /><br />본 서적은 하급 영약을 제조하는 데 필요한 재료를 수집하고 제작하는 과정에서 일어난 사건들에 대한 경험을 담고 있다.<br /><br />부디 이 책이 적들의 손에 들어가지 않기를.<br /><br />부디 살아서 다시 한번 쿠엘탈라스에 창백한 달빛이 비치는 광경을 볼 수 있기를.<br /><br />부디 캘타스님의 은총 속에서 숨을 거두기를.<br /><br />부디 일리단님의 영광을 위해 살생을 하기를.<br /><br />-텔미우스 드림시커$B<img src=\\$B />$B<img src=\\$B />$B<img src=\\$B />' WHERE entry = 1611;
UPDATE locales_page_text SET Text_loc1 = '웜타라크,<br /><br />더 이상 침입자들이 요새 안으로 들어올 경우 내 판단에 따라 그대를 처벌해도 좋다는 직명을 그대의 군주인 네파리안으로부터 받았다.<br /><br />누구의 명령을 따라야 하는지 잊지 말도록 하라.<br /><br />블랙핸드의 아들이자 칼과 전투의 달인이며, 유일하고도 진정한 대족장.<br /><br />-렌드' WHERE entry = 1772;
UPDATE locales_page_text SET Text_loc1 = '이 두 탑이 모두 요새화되고 밴더의 엘리트 지휘관 중 한 사람이 통치하기 때문에 병사를 조심하십시오. 당신 군대가 요새화를 위반한다면, 사령관이 침묵했는지 확인하십시오. 이것 역시 스톰 파이크의 해체의 일부가 될 것입니다.' WHERE entry = 2774;
UPDATE locales_page_text SET Text_loc1 = '내가 아제크에게 오늘 있을 사냥에 집중하지 않는 것에 대한 우려를 표하려는 순간, 그녀가 화살통에서 화살을 하나 꺼내더니 불쌍한 바닐을 향해 쏘는 것이었다. 하지만 아제크가 맞추려 했던 건 바닐이 아니었다. 바닐이 놀라 입을 벌린 채로 옆으로 비켜서자 아제크의 화살이 정확하게 미간 한가운데에 박힌 거대한 민물악어가 수면으로 떠올랐다.' WHERE entry = 100;
UPDATE locales_page_text SET Text_loc1 = '그 살해는 탐험대들 사이에서 축제 분위기를 불러 일으켰습니다. 바닐은 모두가 즐길 수있는 미드를 쏟아 부었다. 그러나 우리의 축제는 오래 가지 못했습니다. 우리가 기지 캠프로 돌아가는 수송을 위해 시체를 준비 할 때 우리는 모두 끔찍한 으르렁 거리에 의해 경계를당했습니다. 내 년 동안 나는 피가 흐트러지기 때문에 아무것도 듣지 못했습니다.' WHERE entry = 104;
UPDATE locales_page_text SET Text_loc1 = '나는 전장에서 수없이 지옥을 드나들었다. 바로 사방에서 공격해 오는 불타는 군단이라는 지옥의 군대를... 그들에 비하면 난폭한 트롤 무리는 던 모로의 언덕을 뛰어다니는 토끼만큼이나 안전하다고 할 수 있다. 우리는 아무 문제 없이 트카시 폐허를 지나왔고 이로써 바닐도 많이 안심하게 되었다. 대해를 향해 서쪽으로 계속 가면서 바로 남쪽에 보이는 줄쿤다의 폐허의 가장자리를 지나쳤다. 높은 해안 절벽을 올라가던 도중에 첫 랩터 사냥감을 발견했다.' WHERE entry = 115;
UPDATE locales_page_text SET Text_loc1 = '우리의 재빠른 조준 사격으로 바닐은 도망칠 수 있었다. 그는 언덕 아래로 도망쳐 와서 우리와 다시 합류했다. 우리는 정글 속으로 도망쳤다. 그러나 포악한 채찍꼬리랩터 무리가 계속 우리를 쫓아왔다. 사냥꾼들이 오히려 사냥감이 되어 버린 것이었다.' WHERE entry = 118;
UPDATE locales_page_text SET Text_loc1 = '나는 해안선이 랩터들로부터 피난처가되기를 희망하면서, 파티를 바다쪽으로 이끌었다. 서두르지도 않고 너무 북쪽으로, 너무 높은 고도로 이동했습니다. 실수가있었습니다. 그 잘못은 내 것이 었습니다. 우리는 깎아 지른듯한 절벽에 그만 두었습니다. 랩터스는 몇 발자국 뒤에 있습니다.' WHERE entry = 119;
UPDATE locales_page_text SET Text_loc1 = '나는 총을 치켜들고 천천히 앞으로 걸어나갔다. 내가 이 용감한 사냥꾼들을 죽음으로 이끈 것이었다. 하지만 나는 사냥꾼답게 의연하게 죽음을 맞이할 것이다...' WHERE entry = 120;
UPDATE locales_page_text SET Text_loc1 = '우리 처음 주간은 갔다. 그리고 사람은 처음 주간을 갈 것을 예상 할 수있다. 우리 시대의 대부분은베이스 캠프를 수립하는 데 필요한 준비를하는 데 몰두했습니다. 나는 담수 강 입구에 의해 이상적인 설정을했다. 근처에 버려진 부두가있는 것으로 판단하여이 지역은 언젠가 거주하게되었습니다. 원래의 거주자에 관해서는 시간 만이 그 이야기를 말할 수 있습니다.' WHERE entry = 153;
UPDATE locales_page_text SET Text_loc1 = '우리는 빽빽하게 우거진 정글을 뚫고 서쪽을 향해 길을 나섰다. 천천히 신중하게 움직이며, 주변의 울창한 덤불 속에 도사리고 있을지 모르는 위험을 경계했다...' WHERE entry = 159;
UPDATE locales_page_text SET Text_loc1 = '그 맹수는 숫가시덤불호랑이였다. 내가 소총의 방아쇠를 당기기도 전에, 얼가딘이 그의 쇠뇌를 치켜들었고...' WHERE entry = 161;
UPDATE locales_page_text SET Text_loc1 = '그 살해는 탐험대들 사이에서 축제 분위기를 불러 일으켰습니다. 바닐은 모두가 즐길 수있는 미드를 쏟아 부었다. 그러나 우리의 축제는 오래 가지 못했습니다. 우리가 기지 캠프로 돌아가는 수송을 위해 시체를 준비 할 때 우리는 모두 끔찍한 으르렁 거리에 의해 경계를당했습니다. 내 년 동안 나는 피가 흐트러지기 때문에 아무것도 듣지 못했습니다.' WHERE entry = 162;
UPDATE locales_page_text SET Text_loc1 = '나는 그 모피가 아제로스 전역에 높은 수요가 있기 때문에 다음날 사냥 표범을 보낼 탐험을 약속했다. 동맹의 이름으로 용맹스럽게 목숨을 바칠 수있는 유능한 사냥꾼, 덫 사냥꾼 및 모피 무역상들 모두와 함께 그러한 요구가 존재해야한다는 것은 의미가 있습니다.' WHERE entry = 164;
UPDATE locales_page_text SET Text_loc1 = '우리의 인간 친구들은 나무들 사이로 숨어 달리는 표범을 쫓으며 눈을 훈련시켰다. 총이 든 통은 서로 잘 묶여 있었다. 바닐은 간절한 눈빛으로 날 쳐다봤지만 나는 고개를 저었다. 이번 사냥은 인간 친구들을 위한 것이지 바닐이나 내가 낄 자리가 아닌 것이다. 얼가딘은 요란하게 총을 쐈지만 모두 빗나갔다. 그리고 그는 총격의 심한 반동에 미처 대비하지 못했던 것 같다.$B그의 총이 반동으로 그의 팔 안에서 심하게 흔들렸다. 그리고 통이 옆으로 떨어져 아제크는 총 아래로 굴러갔다. 아제크는 바로 그 순간 방아쇠를 당겼다. 갑자기 굴러온 통으로 조준이 흐트러져 총알은 뚜렷한 소리를 내며 나무 있는 곳을 향해 발사되고 말았다. 새 떼가 울부짖으며 하늘로 날아올라 사방으로 흩어졌다. 나무에서 연기가 나고 있었다. 우리는 거대한 나뭇가지가 똑바로 떨어져 달아나는 표범의 등을 부러뜨리는 광경을 두려워하며 지켜보았다.$B몇 주가 지나면서 표범과 호랑이 가죽이 상당히 많이 모였다. 이제 사냥감의 수준을 좀 더 높여 랩터를 사냥 할때가 왔다고 판단했다. <br />인간 친구들들은 바닐과 내가 제공한 훈련에 대해 고마워하긴 했지만 소총을 사용한 사냥은 그만 하기로 결정했다. 아제크는 시위가 팽팽하게 잘 조절된 활을 사용하는 데 훨씬 더 익숙했고, 얼가딘 경은 항상 그의 견고한 석궁을 들고 사냥에 나섰다.$B우리는 해가 뜨자마자 트카시 폐허를 지나 남쪽을 향해 출발했다. 바닐은 붉은머리부족과 마주치게 되지 않을까 걱정했다. 나는 바닐에게 붉은머리부족은 그들 일족의 숙적인 백골가루부족를 처치하는 데 여념이 없을 거라고 상기시켜 주었다. 물론 바닐은 전혀 안심하지 않았지만, 나는 장전된 총, 화약을 가득 담은 가방, 그리고 세 명의 뛰어난 사냥꾼이 있어 어떤 적이 습격해 온다 해도 걱정이 없었다.$B나는 전장에서 수없이 지옥을 드나들었다. 바로 사방에서 공격해 오는 불타는 군단이라는 지옥의 군대를... 그들에 비하면 난폭한 트롤 무리는 던 모로의 언덕을 뛰어다니는 토끼만큼이나 안전하다고 할 수 있다.<br /><br />우리는 아무 문제 없이 트카시 폐허를 지나왔고 이로써 바닐도 많이 안심하게 되었다. 대해를 향해 서쪽으로 계속 가면서 바로 남쪽에 보이는 줄쿤다의 폐허의 가장자리를 지나쳤다. 높은 해안 절벽을 올라가던 도중에 첫 랩터 사냥감을 발견했다.$B그 짐승은 우리가 있다는 것을 전혀 알아차리지 못했다. 사실, 놈이 이번에 우리에게 받은 인사라고는 미간에 박힌 총탄뿐이었다. 아제크가 성공을 인정하듯 내게 고개를 끄덕이자 얼가딘 경은 열렬히 *만세*를 외쳤다. 나는 축하의 담배를 한 대 피울 생각으로 파이프를 찾기 위해 짐을 뒤졌다. 바닐은 랩터의 시체를 가져오기 위해 서둘러 언덕을 올라가기 시작했다. 나는 어려운 사냥에 성공할 때면 어김없이 찾아오는 뿌듯한 만족감을 느끼며 쓰러진 짐승을 바라보았다.$B하지만 영광의 순간은 그리 오래가지 않았다. 지평선으로 시선을 돌렸을 때, 불쌍한 바닐 바로 위 언덕에 몇 개의 그림자가 나타났기 때문이다.<br /><br />*도망쳐, 바닐!* 나는 소리쳤다. 아제크, 얼가딘 경, 그리고 나는 바닐의 뒤를 쫓아오는 랩터들을 향해 일제히 총탄과 화살, 그리고 석궁용 짧은 화살을 계속 쏘아 댔다. 그 혼란스러운 상황에서 우리 중 누군가가 한 놈을 처치했다.$B우리의 재빠른 조준 사격으로 바닐은 도망칠 수 있었다. 그는 언덕 아래로 도망쳐 와서 우리와 다시 합류했다. 우리는 정글 속으로 도망쳤다. 그러나 포악한 채찍꼬리랩터 무리가 계속 우리를 쫓아왔다.<br /><br />사냥꾼들이 오히려 사냥감이 되어 버린 것이었다.' WHERE entry = 169;
UPDATE locales_page_text SET Text_loc1 = '나는 해안선이 랩터들로부터 피난처가되기를 희망하면서, 파티를 바다쪽으로 이끌었다. 서두르지도 않고 너무 북쪽으로, 너무 높은 고도로 이동했습니다. 실수가있었습니다. 그 잘못은 내 것이 었습니다. 우리는 깎아 지른듯한 절벽에 그만 두었습니다. 랩터스는 몇 발자국 뒤에 있습니다.' WHERE entry = 177;
UPDATE locales_page_text SET Text_loc1 = '그리고 기적적인 일이 일어났습니다. 떨어져서 우리 쪽에서 우리는 굉장히 하얀 타이거의 별개의 그리고 무서운 포효를 들었다. 그들의 수에도 불구하고, 맹금류는 돌고 모든 방향에서 뿌렸다.우리는 호랑이가 우리를 지나서 뛰쳐 나와 랩터 중 한 명을 놀라게하면서 짧은 플래시를 보았습니다. 명령을 줄 필요가 없습니다. 우리 당원 모두 네가 도망 갈 시간임을 알았다.' WHERE entry = 180;
UPDATE locales_page_text SET Text_loc1 = '...절망의 소용돌이에 빠진 듯하다. 처음에는 날 가지고 놀다가 이제 약혼을 해 버리다니. 처음부터 이 무례한 사기꾼은 결국 나에게 상처를 입힐 작정으로 거짓으로 사랑하는 척했던 것이다. 내 안에 어두운 공허감이 생겨나 매순간 커져 가고 있다. 피보다도 고통스러운 눈물을 얼마나 흘렸던가...' WHERE entry = 24;
UPDATE locales_page_text SET Text_loc1 = '이제이 배럴에서 북쪽으로 향하십시오. 까마귀가 곧장 날아 다닐 때, 바다 절벽의 고독한 풍차 옆에있는 빈 주전자를 볼 때까지 계속 걸으십시오. 너희가 저 주전자 주위를 찌르면 너희가 찾는 것을 찾을 수있을 것이다.' WHERE entry = 46;
UPDATE locales_page_text SET Text_loc1 = '너는 나에게 위스키 주전자를 발견 했으니 너는 거의 보물에있어! 병에서 서쪽을 향하고 해안으로 걸어가십시오. 일단 물에 빠지면 계속 가라.당신이 나에게 보물 상자가있는 섬을 찾을 때까지 서쪽으로 똑바로 수영하십시오!' WHERE entry = 47;
UPDATE locales_page_text SET Text_loc1 = '[...서판의 첫 부분은 닳아 지워졌지만 마지막 부분은 알아볼 수 있습니다...]$B$B그리렉은 정글을 짓밟아 버렸다. 그의 눈은 분노로 불타고 가슴은 우레와 같이 뛰고 있었다. 허공을 향해 분노로 울부짖은 그의 팔을 쳐들었다. 오른쪽 팔을 잃고 나머지 한 쪽 팔만으로 이어온 사냥을 통해 그의 왼쪽 팔은 강하고 튼튼하게 단련되어 있었다. 그는 팔을 찾아 헤맸지만 잃어버린 팔을 찾을 수는 없었다.$B$B그는 그렇게 저주를 퍼붓고 울부짖으며 돌아다녔다. 하지만 그리렉은 오래전부터 정령들에게 귀를 기울이지 않았고 화가 난 정령들은 그의 저주를 아랑곳하지 않았다. 비참한 운명의 그리렉, 그는 팔 없이 헤매야 할 운명을 맞은 것이었다.' WHERE entry = 62;
UPDATE locales_page_text SET Text_loc1 = '카레빈 님,$B$B이 편지를 가져가는 자는 빛의 수호자들의 대열에 합류할 자격이 충분한 의로운 자임을 증명해 보였습니다...' WHERE entry = 63;
UPDATE locales_page_text SET Text_loc1 = '내 일지<br /><br />지난 몇 주 동안의 공포는 참기 힘든 것이었다. 이렇게 일지를 기록하면서 미치지 않고 버틸 수 있게 되는 이유는 무엇일까? 마치 아무 말도 하지 않는 동료에게 죄를 고백하는 것이 마음 속의 괴로운 생각을 종이 위에 풀어놓고 덮어두는 것과 마찬가지이기 때문일지도 모르겠다. 전에도 일지를 썼었지만 그 일지는 내가 돌아갈 수 없는 곳에 남겨져 있다. 그래서 새로 일지를 작성하는 것이다. 하지만 이번에는 진정 처음부터 시작하리라.$B모든 것은 롤랜드 광산에서 그 저주받은 낫을 발견하면서 시작됐다. 낫을 발견하기 전까지 이곳은 노스샤이어 계곡 만큼이나 평온한 곳이었다.<br /><br />정말 후회스럽게도 내가 광산의 돌 무더기 사이에서 튀어나와 있던 낫의 자루를 발견하고 그걸 잡아 꺼내면서부터 롤랜드 광산은 비참한 죽음의 장소가 되어 버렸다.$B무슨 일이 일어날지 진작 알았더라면 룬문자가 새겨진 그 낫 자루를 잡지 못하게 내 손을 잘라 버리기라도 했을 것이다. 이 얼마나 후회스러운 일인가! 후회란 세상을 등지기 전 노인들만 하는 것이라고 생각했었는데... 후회란 노인이 아니라 절망에 빠진 자의 것이란 걸 깨달았다. 후회하는 사람은 외투를 뒤집어쓰고 불행한 운명에 굴복하여 벗을 수도 없고 벗으려는 의지도 없는 자들이다.<br /><br />감상적인 시인들이나 할 법한 얘기는 이쯤에서 그쳐야겠다. 내가 겪은 일들을 계속 기록해야 하니까...$B그 낫이 세상에 모습을 드러낸 이후 광산에 변화의 물결이 일었다. 희미한 횃불에서 나오던 빛이 휘어지고, 우리는 목소리 크기를 스스로 제어할 수 없게 되었다. 어떤 때는 한 사람이 속삭이는 소리가 손으로 귀를 틀어막아야만 할 정도로 굴 속 전체에 크게 울려 퍼지기도 하고, 또 어떤 때는 고함 소리가 채 몇 발자국 거리도 못 가 바람에 묻혀 희미하게 사라져 버리기도 했다.<br /><br />물론 우린 당황했지만 이 이상한 현상에 대한 궁금증은 곧 풀렸다. 그것은 우리를 광산에서 내쫓은 늑대인간의 출현을 알리는 전조였을 뿐이었다.$B놈들이 사방에서 공격해 왔다. 우리 발 아래 숨겨진 구덩이에서 튀어나오기도 하고, 머리 위에서 조용히 떨어져 내리기도 했다. 이렇게 끔찍한 상황이 시작되고 몇 분이 지나지 않아 반이 당하고 말았다. 나를 포함한 나머지 생존자는 필사적으로 도망쳤다. 나는 달려가면서 많은 형제들이 놈들의 이빨과 발톱에 당하는 걸 목격했고, 비명 소리가 짧게 사라지거나 헐떡이다 끊어져 버리는 것을 수없이 들었다.<br /><br />난 그곳을 탈출한 유일한 인간이었던 것이다.$B내가 그날 밤 어떻게 살아남을 수 있었는지 정확히는 모르겠지만 아마도 경계를 늦추지 않고 공격이나 위험으로부터 재빨리 빠져나왔기 때문일 것이다. 내 별명도 이런 성격 탓에 붙여진 것이니 붙여졌다. 이런 나의 조심스러운 성격이 날 구한 것이 아니었을까...?<br /><br />아니면 내가 돌 무더기에서 잡아 꺼낸 낫 때문이었을 수도... 정신없이 도망치는 동안 그 낫을 잃어버렸으니까 그것도 아닐 것이다. 하지만 어쨌든 나 때문에 늑대인간이 그늘숲에 나타난 것이니 늑대인간 놈들도 내게 일종의 예의를 차린 것 아니었을까? 저주받을 놈들!$B아니면 내가 그늘숲에 일으킨 변화의 목격자가 되는 비참한 운명을 타고난 것인가? 아마도 늑대인간이 이 땅을 짓밟고 그 사악함으로 세상을 끝없이 더럽히는 것을 지켜보는 것이 내 운명일지도...<br /><br />진정 그것이 내 운명이라면, 나에게 닥친 시련은 그것뿐만이 아닐 것이다. 그늘숲을 차지하려는 세력은 늑대인간만이 아니다. 죽음의 고개에서 나타난 악귀들도 이 땅을 노리고 있는 것이다.<br /><br />그들에 대해서는 다음 장에서 쓰도록 하겠다. 그리고 이 땅을 노리는 자들이 그들이 마지막이 되길 바랄 뿐이다...$B롤랜드 광산에서 무사히 도망친 후, 나는 스벤이라는 자의 헛간에 숨었다. 그 헛간에서 며칠을 지냈지만 계속 공포에 휩싸여 있었기 때문에 스벤이나 그의 가족이 보지 못하게 숨어있었다. 하지만 숨어서 지켜보니 농부가족인 이들은 매우 좋은 사람들이었다. 그때 내가 헛간에서 나갔다면 그들이 안전하게 나를 숨겨 줬었겠지만, 당시 누군가를 믿는다는 건 내게 너무 어려운 일이었다. 광산에서 그 충격적인 일을 겪은 후로는 더욱 그랬다. 그래서 나는 숨어 있었고 그것이 나를 살렸다.$B내가 헛간에 숨어 지낸 지 며칠이 지난 후, 스벤은 다크샤이어로 떠나기 위해 농장을 나섰다. 그는 아내에게 작별의 입을 맞추고 아이들에게 미소를 지어 보이고는, 곧 장난감과 과자를 사 가지고 돌아오겠다는 약속과 함께 길을 나섰다. 불쌍한 사람, 그것이 가족들의 모습을 본 마지막이었다. 그래도 그들은 마지막 순간에 행복하게 헤어질 수 있지 않았는가. 또 그의 아내가 먼저 죽었으니 아이들의 처참한 죽음을 목격하고 피눈물을 흘리는 일은 피할 수 있지 않았던가. 하지만, 내게는 이런 작은 자비도 허락되지 않았다. 난 모든 걸 목격했고, 그 모습은 악몽으로 나타나 영원히 나를 괴롭힐 것이다.$B스벤이 떠나고 집에 남아 있던 그의 가족이 흑기사의 습격을 당하던 그날 밤의 악몽이 생생히 떠올라 내 손이 떨리면서 또다시 후회가 밀려온다. 내가 뛰쳐나가 죽음의 고개에서 온 저 악귀들과 맞서 싸웠어야 하는데... 이미 되돌릴 수 없는 후회일 뿐이다. 참사에서 살아남은 생존자라면 누구나 이러한 후회에 시달리게 된다. 설령 내가 숨어 있던 곳에서 뛰쳐나갔다 하더라도 나 역시 죽임을 당하고, 내 시체가 조각조각 찢겨 사방으로 흩어져서 형체도 알아볼 수 없게 되었으리란 걸 잘 알고 있다.$B하지만 내가 이 극악무도한 살인을 막기 위해 할 수 있는 건 아무것도 없었지만 정말 후회스러운 게 있다. 바로 내가 흑기사들을 스벤의 농장에 불러들였다는 것이다. 내가 낫을 발견했기 때문에 늑대인간들이 그늘숲에 풀려났을 뿐더러 죽음의 고개에서 흑기사를 불러들이기까지 한 것이다. 놈들은 가족을 몰살시키기 전 아이들을 꼭 안고 있던 스벤의 아내에게 한 가지 질문을 했었다. 이 대화를 통해 내가 이 엄청난 파장의 씨앗이라는 사실을 알게 되었다. 그녀는 죽음이 가까이 온 것을 분명히 느끼면서도 최대한 아이들을 안심시키기 위해 애쓰고 있었다.$B\\$B 흑기사 중 하나가 마치 돌에 도끼를 가는 듯한 거칠고 날카로운 목소리로 소리쳤다. 그리고 말이 끝날 때쯤에는 - 엘룬 - 이라고 목이 멘 듯 쉰 목소리가 났다.<br /><br />그 목소리는 공포 그 자체였다. 소리가 무시무시하기도 했었지만... 나는 그들이 얘기하는 낫이 무엇인지 알고 있었기 때문이었다. 그것은 며칠 전 내가 롤랜드 광산의 돌 더미에서 꺼낸 그 저주받은 물건을 말하는 것이 분명했다. 그게 흑기사들이 찾고 있는 물건이었다니! 그리고 그때문에 스벤의 가족이 죽임을 당하다니...$B\\ud56d\\uc0c1 \\ub0a8\\ud3b8\\uc774\\ub098 \\uc544\\uc774\\ub4e4\\uc5d0\\uac8c \\uc2a4\\ubca4\\uc758 \\uc544\\ub0b4\\uc758 \\ud638\\uce6d\\uc740 \\$B, \\$B, \\$B 등이었기 때문에 난 그녀의 이름을 알지 못했다. 그녀의 이름을 알았더라면 좋았을 텐데... 난 그날 그녀의 마지막 모습을 기억하고 있는 유일한 사람이고, 비록 일개 농부의 아내일 뿐이었지만 지금까지 내가 봐 온 어떤 사람보다도 용감한 사람이었다.<br /><br />물론 그녀는 낫에 대해 모르고 있었지만 흑기사가 그걸 찾고 있다는 사실을 눈치채고 곧 작전을 생각해 냈다. 정말 대담하고도 영리한 작전이었다. 성공했더라면 정말 좋았을 것을...$B\\$B \\uc870\\uc6a9\\ud55c \\ubaa9\\uc18c\\ub9ac\\ub85c \\uadf8\\ub140\\uac00 \\ub300\\ub2f5\\ud588\\ub2e4. \\$B \\uadf8\\ub140\\ub294 \\ud754\\ub4e4\\ub9bc \\uc5c6\\uc774 \\ud751\\uae30\\uc0ac\\ub97c \\uccd0\\ub2e4\\ubd24\\ub2e4. \\ub9cc\\uc57d \\ub0b4\\uac00 \\uc9c4\\uc2e4\\uc744 \\ubaa8\\ub974\\uace0 \\uc788\\uc5c8\\ub2e4\\uba74 \\ub098\\uc870\\ucc28\\ub3c4 \\uadf8\\ub140\\uac00 \\uc0ac\\uc2e4\\uc744 \\ub9d0\\ud560 \\uac83\\uc774\\ub77c\\uace0 \\ubbff\\uc5c8\\uc744 \\uac83\\uc774\\ub2e4. \\uadf8\\ub140\\uac00 \\ub0ab\\uc5d0 \\ub300\\ud574 \\uc54c\\ub9ac\\ub294 \\uc5c6\\uc5c8\\ub358 \\uac83\\uc774\\ub2e4.<br \\/>\\ud558\\uc9c0\\ub9cc \\uadf8\\ub140\\uc758 \\uac70\\uc9d3\\ub9d0\\uc774 \\ud6a8\\uacfc\\ub97c \\ubc1c\\ud718\\ud588\\ub2e4. \\uc870\\uae08 \\uc804 \\uc9c8\\ubb38\\uc744 \\ud588\\ub358 \\ud751\\uae30\\uc0ac\\uac00 \\uadf8\\ub140\\ub97c \\ud5a5\\ud574 \\uace0\\uac1c\\ub97c \\uc57d\\uac04 \\uc219\\uc774\\uace0\\ub294 \\uc678\\ucce4\\ub2e4. \\$B \\$B 그녀가 대답했다. 그녀의 눈 속에 작은 희망이 희미하게 빛나는 것을 볼 수 있었다.$B\\$B \\uadf8\\ub140\\uc758 \\uc18d\\uc784\\uc218\\ub294 \\ub2e8\\uc21c\\ud588\\uc9c0\\ub9cc, \\uc6d0\\ub798 \\ub2e8\\uc21c\\ud55c \\uc18d\\uc784\\uc218\\uac00 \\uac00\\uc7a5 \\uc798 \\uba39\\ud788\\ub294 \\ubc95\\uc774\\ub2e4. \\uc131\\uacf5\\ud588\\ub354\\ub77c\\uba74 \\ud751\\uae30\\uc0ac\\ub4e4\\uc744 \\ub18d\\uc7a5\\uc5d0\\uc11c \\uba40\\ub9ac \\ub370\\ub824\\uac08 \\uc218 \\uc788\\uc5c8\\uc744 \\uac83\\uc774\\ub2e4. \\uadf8\\ub7ec\\uba74 \\uadf8\\ub140 \\uc790\\uc2e0\\uc740 \\uc0b4\\uc544\\ub0a8\\uc9c0 \\ubabb\\ud558\\ub354\\ub77c\\ub3c4 \\uc544\\uc774\\ub4e4\\ub9cc\\uc740 \\uc0b4\\ub9b4 \\uc218 \\uc788\\uc5c8\\uc744 \\uac83\\uc774\\ub2e4. \\uadf8\\ub9ac\\uace0 \\ud751\\uae30\\uc0ac\\uac00 \\uadf8\\ub140\\uc758 \\uc9c0\\ud61c\\ub85c\\uc6b4 \\uac70\\uc9d3\\ub9d0\\uc744 \\ubbff\\uae30\\ub9cc \\ud588\\ub354\\ub77c\\uba74 \\uc131\\uacf5\\ud588\\uc744 \\uac83\\uc774\\ub2e4. \\ub09c \\uc2e0\\uc744 \\ubbff\\uc740 \\uc801\\uc774 \\uc5c6\\uc5c8\\uc9c0\\ub9cc, \\uc800 \\ub054\\ucc0d\\ud55c \\ud751\\uae30\\uc0ac\\uc640 \\ub9de\\uc11c\\uace0 \\uc788\\ub294 \\uc2a4\\ubca4\\uc758 \\uc544\\ub0b4\\ub97c \\uc704\\ud574 \\uc5f4\\uc2ec\\ud788 \\uae30\\ub3c4\\ud588\\ub2e4. <br \\/><br \\/>\\$B$B놈들은 꼼짝도 않고 서 있었고 그녀는 태연하게 그들의 시선을 받고 있었다. 그리고는 놈들 중 하나가 멀리서 부르는 소리라도 들리는 듯이 위를 쳐다보았다. 놈은 자신의 품 속에서 작은 보석을 꺼내 들여다보았다. 그리고는 스벤의 아내에게 그 보석을 내밀었다. 그 흑기사의 손에서 빛이 나와 기분 나쁜 흰색 손 모양으로 변해 그녀를 향했다. 그녀는 똑바로 빛을 응시했지만 나는 그녀의 자신감 넘치는 얼굴 뒤에 감춰진 불안감을 읽을 수 있었다. 그 손은 그녀에게 닿자 손가락을 펴 그녀의 머리를 감싸고는 쥐어짰다.$B\\uc2a4\\ubca4\\uc758 \\uc544\\ub0b4\\ub294 \\ud310\\uc790\\ucc98\\ub7fc \\uad73\\uc740 \\ucc44\\ub85c \\uc11c \\uc788\\uc5c8\\uace0 \\ub208\\ub3d9\\uc790\\ub294 \\ucee4\\uc84c\\ub2e4. \\ube44\\uba85\\uc744 \\uc9c0\\ub974\\uae30 \\uc704\\ud574 \\uc785\\uc744 \\ubc8c\\ub838\\uc9c0\\ub9cc \\uc5b4\\ub5a4 \\uc18c\\ub9ac\\ub3c4 \\ub4e4\\ub9ac\\uc9c0 \\uc54a\\uc558\\ub2e4. \\uc774 \\ub054\\ucc0d\\ud55c \\uc21c\\uac04\\uc774 \\uba87 \\ubd84 \\ub3d9\\uc548 \\uacc4\\uc18d\\ub41c \\ud6c4 \\uadf8 \\uc190\\uc740 \\uadf8\\ub140\\ub97c \\ub193\\uc544 \\uc8fc\\uc5c8\\uace0 \\uadf8\\ub140\\ub294 \\ubc14\\ub2e5\\uc5d0 \\uc4f0\\ub7ec\\uc84c\\ub2e4. \\uadf8\\ub9ac\\uace0\\ub294 \\ubcf4\\uc11d\\uc744 \\uac00\\uc9c4 \\ud751\\uae30\\uc0ac\\uac00 \\ub9d0 \\uc548\\uc7a5\\uc5d0 \\uc62c\\ub77c\\ud0c0\\ub354\\ub2c8 \\ucee4\\ub2e4\\ub780 \\ubaa9\\uc18c\\ub9ac\\uac00 \\ubfdc\\uc5b4\\uc838 \\ub098\\uc654\\ub2e4.<br \\/><br \\/>\\$B \\uc774 \\ubaa9\\uc18c\\ub9ac\\ub294 \\uadf8 \\ud6c4 \\ub0b4\\uac00 \\uafb8\\ub294 \\uc545\\ubabd\\uc5d0 \\uacc4\\uc18d \\ub098\\ud0c0\\ub098\\uace0 \\uc788\\ub2e4. \\$B$B\\uadf8\\ub7ec\\uace0 \\ub098\\uc11c \\uadf8 \\ud751\\uae30\\uc0ac\\ub294 \\ubab8 \\uc18d\\uc758 \\uc601\\ud63c\\uc774 \\ube60\\uc838 \\ub098\\uac00\\uae30\\ub77c\\ub3c4 \\ud55c \\ub4ef \\uc5b4\\uae68\\ub97c \\uc57d\\uac04 \\uad7d\\ud614\\ub2e4. \\uadf8\\ub9ac\\uace0 \\ub9c8\\uc9c0\\ub9c9\\uc73c\\ub85c \\uc804\\uacfc \\uac19\\uc774 \\ub299\\uace0 \\ub0a0\\uce74\\ub85c\\uc6b4 \\ubaa9\\uc18c\\ub9ac\\ub85c \\uc774\\ub807\\uac8c \\uc678\\ucce4\\ub2e4.<br \\/><br \\/>\\$B<br /><br />그 뒤에 일어난 일은 설명할 수가 없다. 기억에 또렷이 남아 있긴 하지만 내 비열한 영혼조차도 차마 그 후의 끔찍했던 몇 분 동안 일어난 일들을 종이 위에 옮기지는 못하겠다.$B그저 스벤의 가족이 모두 죽었다는 것만 말할 수 있다. 그리고 얼마 지나지 않아 스벤이 이 끔찍한 죽음의 현장으로 돌아왔다. 나는 그의 깊은 슬픔 앞에 내 모습을 나타내기가 두려웠다. 그리곤 그가 나를 발견하게 될까 두려운 나머지 숨어 있던 헛간에서 도망쳐 나왔다. 나는 지금 스벤이 어디에 있는지 모르지만 그가 언젠가 평온을 되찾게 되기를 빈다.<br /><br />그 후 몇 주 동안 이곳 저곳으로 피해 다녔다. 흑기사에 대한 두려움 때문에 어디에서도 지체할 수가 없었다.$B지금 나는 언제나 그랬던 것처럼 까마귀 언덕의 버려진 마을에 숨어 있다. 놈들이 스벤의 아내에게 사용했던 그 힘이 무엇이든 나는 그 힘을 감당할 수가 없다. 그리고 놈들이 아직까지도 그 낫을 찾기 위해 그늘숲을 수색하고 있다는 사실을 알고 있다. 그 낫이 지금 내 손에 없다는 것에 대해 신께 감사한다. 만약 내가 지금까지 그걸 가지고 있었더라면 이미 놈들에게 발각됐을 것이다. 지금도 마음 속으로는 언젠가 놈들이 나를 발견할 것이라는 것을 알고 있다.<br /><br />난 너무 지쳤다.' WHERE entry = 85;
UPDATE locales_page_text SET Text_loc1 = '그들은 우리 발에 숨어있는 구멍에서 발톱을 떼어 내고 위의 침묵하는 곳에서 우리를 떨어 뜨 렸습니다. 우리 남자 절반이 처음 공포에 빠졌습니다. 나 자신을 포함한 나머지 사람들은 도망 가려고했습니다. 내가 달려 갔을 때 나는 많은 형제들이 이빨과 발톱으로 끌려 갔다는 것을 보았고, 너무 많은 비명 소리가 들리거나 소리가 나지 않게 들렸다는 말을 들었다. 나가 알고있는 모두를 위해, 나는 그 장소를 도주하는 유일한 인간이다.' WHERE entry = 189;
UPDATE locales_page_text SET Text_loc1 = '나는 그녀가 남편과 아이들에 의해서 \"사랑스럽고\", \"내 사랑\", 그리고 \"엄마\"로만 불렸을 때 스벤의 아내의 이름을 결코 알지 못했다. 그러나 나는 그것을 알고 있었으면 좋겠다.나는 그날 그녀의 유일한 생존 기념품이며, 그녀는 농부의 부인 이었지만 남자 또는 여자가 용감한 행동을하는 것을 본 적이 없었다. 당연히 그녀는 낫을 알지 못했지만 그녀가 라이더들이 그녀의 머리에 형성된 계획을 즉각적으로 찾았다는 것을 알았을 때. 그리고 그것은 대담하고 영리했습니다.그것이 작동했다면.' WHERE entry = 197;
UPDATE locales_page_text SET Text_loc1 = '\"낫?\" 그녀는 조용한 목소리로 말했다. \"당연하지. 누가 여기 있지?\" 그녀는 꾸준한 눈으로 라이더를 바라 보았습니다. 나는 더 잘 알지 못한다면 그녀가 진실을 말했을 것이라고 맹세했습니다. 그녀가 낫에 대해 알 수있는 방법이 없었습니다. 그녀의 겜비가 갚았습니다. 같은 라이더가 질문을 한 후에 머리를 약간 구부리고 \"어디서?\"라고 외쳤다. \"나는 너를 데려 갈거야. 너 모두.\"그녀가 말했다. 나는 그녀의 눈 뒤에 작은 희망의 깜박임을 볼 수 있었다.' WHERE entry = 198;
UPDATE locales_page_text SET Text_loc1 = '스벤의 아내는 널빤지로 단단히 서 있었고 눈은 크게 자랐다. 그리고 그녀의 입술이 비명 소리를 입으로 가져 왔지만 소리가 빠져 나가지 않았습니다. 이 고문을당한 순간 손이 그녀를 풀어 무릎을 꿇었다. 지팡이를 든 라이더는 안장에 서서 앉았고 큰소리로 소리가났습니다. \"이 여자는 거짓말을한다.\"라고 목소리를 높여 내 꿈을 상실했다. \"그녀는 낫을 보지 못했다.\"' WHERE entry = 201;
UPDATE locales_page_text SET Text_loc1 = '그 후, 라이더의 어깨는 마치 그 안에있는 정신이 도망 치듯이 약간 구부렸다. 그리고 이전에 사용했던 낡은 비명 소리에서이 마지막 단어가 나왔습니다.$B$B \"주님 께서 말씀하셨습니다. 그들을 죽이십시오.\"' WHERE entry = 202;
UPDATE locales_page_text SET Text_loc1 = '사랑하는 타렐에게<br />서둘러 답장을 써서 미안해요. 하지만 지금 이곳에서는 시간이 넉넉지 않답니다.<br /><br />발굴단은 상당한 진척을 이루어 중요한 티탄 유물들을 발굴해 냈어요. 그런데 추가로 커다란 뼈와 같은 다른 고대 유물들도 발견되기 시작했어요.$B뼈 발굴이 시작되고 얼마 지나지 않아 우린 랩터의 공격을 받고 말았어요. 롱브레이드 연대 소속 병력이 용감히 맞서 싸웠지만 결국 놈들에게 제압당하고 말았죠. 거의 전멸하고 우리 세 명만 살아남았으니까요. 오머 아이언브레이드라는 인부가 저와 발굴조사단장 웰가르님을 안전하게 지켜 줬어요. 얼마나 용감하던지...$B지금은 안전한 동굴에 피신해 있어요. 별다른 위험은 없을 것 같아 보이지만 랩터를 처리할 병력이 투입될 때까지 우린 꼼짝없이 갇히게 됐어요. 웰가르님은 작업을 계속하려고 하시지만 아직도 많이 겁을 먹고 계신 것 같아 보여요. 지금 우리는 이런 상황이에요, 타렐. 즉시 구조 병력을 보내도록 롱브레이드님을 설득해 주세요.<br /><br />이런 절박한 상황에서도 당신을 향한 제 사랑은 너무나 강하답니다.<br /><br />- 당신의 아내 메린' WHERE entry = 92;
UPDATE locales_page_text SET Text_loc1 = '\\uc2a4\\ud1b0\\uc708\\ub4dc \\ub3c4\\uc2dc \\uac74\\ucd95\\uacfc \\ubc14\\ub85c\\uc2a4 \\uc54c\\ub809\\uc2a4\\ud134 \\uc62c\\ub9bc.<br \\/>\\ud3d0\\ud558, \\uc81c\\uac00 \\uc774\\ub807\\uac8c \\ucd5c\\uadfc \\ubc1c\\uc0dd\\ud558\\uace0 \\uc788\\ub294 \\$B 관련 사건과 왕국 전역에 걸친 활동에 대해 보고하는 데는 여러가지 이유가 있습니다.<br /><br />이해를 돕기 위해 지금까지의 확인된 내용에 대해서 말씀 드리겠습니다. 폐하께서도 알고 계실지 모르지만 저는 석공 길드의 일원으로 스톰윈드를 위해 일하기 시작했습니다. 수년 간의 노력으로 스톰윈드의 재건은 완료되었습니다.$B그동안 석공 길드에서 청구한 비용과 임금은 지급되지 않았을 뿐만 아니라 이에 대한 언급조차 전혀 없었습니다.<br /><br />그 당시 에드윈 밴클리프가 석공 길드의 장으로 선출되어 이 문제를 제기하면서 공사 비용 상환을 요구했습니다. 이에 대한 반응으로 스톰윈드 귀족 평의회는 석공 길드의 해체를 명했고, 당연히 밴클리프는 이에 분개했습니다. 그는 폭동을 일으켜 석공 길드원들을 이끌고 스톰윈드를 떠났습니다.$B이야기를 계속하기 전에 먼저 당시에 일어났던, 폐하께서 아셔야 할 몇 가지 다른 일들에 대해 말씀 드리겠습니다.<br /><br />첫 번째로, 제가 밴클리프와 동조하지 않는다면 도시 건축가라는 자리를 주겠다는 제의를 받은 것도 이 당시입니다. 그와 근본적인 견해 차이 때문에 저는 스톰윈드에 남기로 결정했습니다.<br /><br />폭동 중에 밴클리프의 부관이자 그가 가장 신뢰하는 협력자였던 바질 스레드가 체포되어 수감되었습니다. 재판과 심문을 기다리는 동안 감옥에 갇힌 스레드는 거의 잊혀져 갔습니다.$B밴클리프에 대한 이야기로 돌아와서, 그는 나머지 석공 길드원들을 이끌고 스톰윈드를 탈출한 후, 자신의 구축한 상당 수의 병력을 활용하여 상대적으로 방어가 취약했던 서부 몰락지대에서 많은 농부들을 내쫓고 몇 개의 금광을 차지했습니다.<br /><br />자원을 손에 넣은 밴클리프는 스톰윈드 정부에 보복을 획책하기에 이르렀습니다.<br /><br />이 정보는 지금 이 문서를 전달하는 자의 도움으로 최근 밝혀진 것입니다.' WHERE entry = 219;
UPDATE locales_page_text SET Text_loc1 = '베소르 아이스샤드 경<br /><br />경의 뜻에 따라 요청하신 요원을 보냅니다. 바로 이 명령서를 가져가는 이가 적임자입니다.<br /><br />이 자는 믿을 만하고 충분히 명령을 수행할 능력이 있음을 보여 주었습니다. 스컬지 군대를 상대로 능력을 입증해 보인 자이니만큼 경의 임무에 적격일 거라고 생각합니다.<br /><br />여왕 폐하의 영광이 있기를...<br />- 집정관 세브렌 올림' WHERE entry = 244;
UPDATE locales_page_text SET Text_loc1 = '발릭,<br />우리가 돌아올 때까지 노예를 잘 지키고 있도록 하라. \'그것\'을 이곳에 두는 것은 이제 안전하지 않다. 우리는 아무도 눈치채지 못하게 북쪽으로 이동할 것이다. <br /><br />녀석들은 짐승에 지나지 않지만 포악한 짐승들이 무리를 이루면 걱정할 만한 이유가 되지. 그러니 녀석들의 성질을 건드릴 만한 것들은 모조리 숨기는 게 좋아. 녀석들이 무리를 지어 공격해오면 안 되니까 말이야.' WHERE entry = 249;
UPDATE locales_page_text SET Text_loc1 = '힐스브래드 마을의 기록부<br /><br />우리 힐스브래드 주민은 위대한 군주이신 아이언포지의 왕 마그니 브론즈비어드 폐하와 스톰윈드의 왕 안두인 린 폐하께서 다스리는 동맹에 대한 믿음과 헌신을 엄숙히 맹세합니다.<br /><br />위대한 알터랙 산맥 기슭에 위치한 이 아름다운 도시를 관리하고, 폐하와 위대하고 절대적인 동맹에 세금을 납부한 이들을 기록하기 위해 여기에 마을 기록부를 작성합니다.$B집정관 리더퍼드 번사이드: 부채 전액 상환.<br />대장장이 에이버리 베링턴: 부채 전액 상환.<br />서기 호레이스 화이트스티드: 부채 전액 상환.<br />원로 길리스: 부채 전액 상환.<br />원로 후크: 부채 전액 상환.<br />농부 게츠: 부채 전액 상환.<br />농부 레이: 미상환 부채. 추수 시 농산품으로 상환 약속.<br />농부 라이언: 미상환 부채. 지역에서 퇴거.$B농부 칼라바: 미상환 부채. 추수 시 농산품으로 상환 약속.<br />민간인 윌키스: 부채 전액 상환.<br />민간인 보노안: 부채 전액 상환.<br />광부 웰티: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.<br />광부 시드니: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.<br />광부 하켓: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.$B광부 오웰: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.<br />광부 피츠제럴드: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.<br />민간인 네더런드: 부채 전액 상환.<br />민간인 메이: 부채 전액 상환.<br />현장감독 본즈: 미상환 부채. 청금석 광산으로부터 다음 광석 도착 시 상환 예정.' WHERE entry = 261;
UPDATE locales_page_text SET Text_loc1 = '[...서판의 첫 부분은 닳아 지워졌지만 마지막 부분은 알아볼 수 있습니다...]$B$B그리렉은 정글을 짓밟아 버렸다. 그의 눈은 분노로 불타고 가슴은 우레와 같이 뛰고 있었다. 허공을 향해 분노로 울부짖은 그의 팔을 쳐들었다. 오른쪽 팔을 잃고 나머지 한 쪽 팔만으로 이어온 사냥을 통해 그의 왼쪽 팔은 강하고 튼튼하게 단련되어 있었다. 그는 팔을 찾아 헤맸지만 잃어버린 팔을 찾을 수는 없었다.$B$B그는 그렇게 저주를 퍼붓고 울부짖으며 돌아다녔다. 하지만 그리렉은 오래전부터 정령들에게 귀를 기울이지 않았고 화가 난 정령들은 그의 저주를 아랑곳하지 않았다. 비참한 운명의 그리렉, 그는 팔 없이 헤매야 할 운명을 맞은 것이었다.' WHERE entry = 285;
UPDATE locales_page_text SET Text_loc1 = '트롤의 전설, 제 3권 해일의 돌<br />저자: 대마법사 앤자이럼 룬위버<br />달라란<br />서문<br /><br />고대 구루바시 제국은 매우 매혹적이고 흥미로운 전설의 근원이다. 이 전설은 그들의 주변 환경에 대한 신념과 사회적 규범에 대한 고찰로 자연을 향한 위대한 숭배 정신에 초점을 맞추고 있다. 본 연구의 이전 부분에서는 그들의 뱀 숭배의 여러 가지 측면에 대해 자세히 살펴봤다.$B지금부터는 트롤과 바다의 흥미롭고 독특한 관계에 대해 알아보고자 한다.<br /><br />대해<br />구루바시 제국은 삼면이 바다로 둘러싸여 있었기 때문에 그들의 사회에서 물이 중요한 의미가 있었던 것은 너무나 당연한 일이라 할 수 있다. 트롤은 그들의 정글 제국을 누비며 광활한 영토를 지배했지만 바다는 쉽게 그들에게 정복되지 않았다. 바다는 광대하고 무한했으며, 강력한 트롤들조차 쩔쩔매게 하는 이웃이었다.$B최근 밝혀진 사실들로 미루어 볼 때 트롤들은 대해 너머의 땅을 탐험하는 데는 거의 관심이 없었던 것 같다. 트롤 종족은 아제로스, 카즈 모단, 그리고 로데론에 이르는 광활한 지역에서 만날 수 있지만, 새롭게 발견된 칼림도어의 땅이나 남쪽 바다의 섬에서는 그들 문명의 흔적이 거의 발견되지 않았다. 이러한 사실이 트롤이 그들의 대륙 영토에만 머물고 더 멀리까지는 진출하려 하지 않았음을 나타내는 것인지,$B아니면 대양을 항해하기 위해 필요한 기술을 개발하는 데 실패했음을 의미하는 것인지를 밝히기 위해서는 본 글의 범위를 넘어서는, 더욱 심도 있는 조사와 분석이 이루어져야 할 것이다.<br /><br />하지만 누구도 그 거대한 문명의 존재를 부정할 수 없거니와, 가시덤불 골짜기의 광활한 트롤 폐허에서 새로 발견된 자료들은 이전에는 알려지지 않았거나 문헌에 기록되지 않았던 트롤과 바다의 관계를 보여 주고 있다.$B\\ud574\\uc77c\\uc758 \\ub3cc<br \\/>\\uac00\\uc2dc\\ub364\\ubd88 \\uace8\\uc9dc\\uae30\\uc758 \\ud2b8\\ub864 \\ud3d0\\ud5c8\\uc5d0 \\ub300\\ud55c \\uc870\\uc0ac\\ub97c \\ud1b5\\ud574 \\ucd5c\\uadfc \\uc0c8\\ub85c \\ubc1c\\uacac\\ub41c \\uc790\\ub8cc\\ub4e4\\uc740 \\$B이라 알려진 유물에 대해 언급하고 있다. 트롤 전설의 여러 부분들을 조합해 보면 해일의 돌과 이 돌이 고대 구루바시 제국이 갖는 중요성에 대해 좀 더 전체적으로 파악할 수 있을 것이다.<br /><br />해일의 돌은 그것을 지니고 있는 자에게 여러 형태의 물, 강, 비, 조류 등을 제어할 수 있는 능력을 부여했던 것으로 보인다. 해일의 돌의 사용과 관련된 여러 이야기들로 미루어$B나는 그것이 실제로 강력한 바다 정령인 바다제왕의 힘을 물리적으로 형상화한 것이라고 추측해 왔다. 그런 물건이 어떻게, 그리고 왜 바다제왕의 통제에서 벗어나 트롤의 손에 들어갔느냐 하는 것은 나로서는 알 수 없는 또 다른 의문점이다.<br /><br />해일의 운반자<br />그 이름의 기원이 된 조류가 넘실대듯 해일의 돌은 트롤과 함께하다가 이들을 떠났으며, 한 번에 한 세대 이상 오랜 기간 동안 꾸준히 트롤이 소유했던 적은 없었다.$B트롤 전설에 따르면 해일의 돌은 가시덤불 골짜기 해안을 따라 여행하던 한 트롤 전사에 의해 발견되어 처음으로 구루바시 제국에 들어가게 되었다고 한다. 트롤 전사는 내부에 우유처럼 흰 가닥들이 떠서 흘러 다니는 신비한 푸른 돌을 우연히 발견했다. 돌에 흥미를 느낀 전사는 돌을 가지고 여행을 계속했다.<br /><br />몇 주 그리고 몇 달의 시간이 흐르면서 전사는 그 돌이 자신에게 물을 제어할 수 있는 능력을 주었다는 사실을 알게 되었다. 그는 물의 정령과,$B\\uc644\\uc804\\ud788 \\ubb3c\\ub85c\\ub9cc \\uc774\\ub8e8\\uc5b4\\uc9c4 \\uc0dd\\uba85\\uccb4\\ub97c \\ubd88\\ub7ec\\ub0bc \\uc218 \\uc788\\uc5c8\\ub2e4. \\uadf8\\uac83\\uc740 \\ud0a4\\ub9b0 \\ud1a0\\uc758 \\uac15\\ub825\\ud55c \\ub9c8\\ubc95\\uc0ac\\ub4e4\\ub9cc\\uc774 \\ud589\\ud560 \\uc218 \\uc788\\ub294 \\ub9c8\\ubc95\\uc5d0 \\ud574\\ub2f9\\ud558\\ub294 \\uac83\\uc774\\uc5c8\\ub2e4.<br \\/><br \\/>\\uc804\\uc0ac\\ub294 \\uc0c8\\ub85c \\ubc1c\\uacac\\ud55c \\ub2a5\\ub825\\uc744 \\ud669\\uc81c\\uc5d0\\uac8c \\ubcf4\\uc774\\uae30 \\uc704\\ud574 \\uc81c\\uad6d\\uc758 \\uc218\\ub3c4\\uc778 \\uc904\\uad6c\\ub8f9\\uc73c\\ub85c \\ud5a5\\ud588\\ub2e4. \\uadf8\\uac00 \\uc81c\\uad6d \\uc218\\ub3c4\\uc758 \\uc911\\uc2ec\\ubd80\\uc5d0\\uc11c \\uadf8 \\ud798\\uc744 \\uc120\\ubcf4\\uc774\\uc790 \\uc27d\\uac8c \\uc655\\uad81\\uc758 \\uc8fc\\ubaa9\\uc744 \\ubc1b\\uac8c \\ub418\\uc5c8\\ub2e4. \\uadf8 \\ud798\\uc5d0 \\ud06c\\uac8c \\ub180\\ub780 \\uad6c\\ub8e8\\ubc14\\uc2dc \\ud669\\uc81c\\ub294 \\uc989\\uc2dc \\uc804\\uc0ac\\uc5d0\\uac8c \\uc655\\uad81\\uc758 \\uba85\\uc608\\ub85c\\uc6b4 \\uc9c0\\uc704\\ub97c \\uc8fc\\uace0 \\$B라는 이름을 하사하여 옛 이름 대신 사용하도록 했다.$B해일의 운반자는 전투에서 그의 명령에 따르는 물의 정령을 불러내고 가시덤불 골짜기의 물이 제국에 유리한 방향으로 흐르도록 조작하며 여러 해 동안 구루바시 제국을 위해 일했다. 하지만 세월이 흐르면서 해일의 운반자는 점점 더 은둔 생활에 빠져들어 왕궁을 떠나 지내는 시간이 길어졌다.<br /><br />해일의 운반자는 왕궁의 감시의 눈길을 피해 한 가지 비밀을 숨기고 있었다. 해일의 돌은 그에게 그러한 능력과 함께 저주를 내렸던 것이다. 몇 해가 지나면서$B해일의 운반자는 서서히 모습을 감췄다. 죽음을 맞이할 때까지 밀물과 썰물이 반복될 때마다 해일의 운반자는 그 존재가 사라졌다가 나타나기를 반복하면서 점점 몸의 형태를 잃고 사라져갔다. 결국 마지막에는 그가 맨 처음 해일의 돌을 발견했던 해변으로 돌아가서는 바다로 걸어 들어가 영원히 사라져 버렸다.<br /><br />수세대가 지난 후, 해일의 돌은 가시덤불 골짜기 해변으로 휩쓸려왔고 또 다른 해일의 운반자가 선택되어 그 트롤이 해일의 돌을 다시$B줄구룹으로 가져왔다. 이런 식으로 수세대 동안 해일의 돌은 조류와 함께 모습을 나타냈다가 다시 해일 속으로 해일의 운반자와 함께 사라지기를 반복했다.<br /><br /><br />오늘날 곳곳에서 해일의 돌에 대한 이야기들이 전해지지만, 왜 그런 힘을 가진 물건이 그토록 규칙적으로 나타나며, 과연 누가 그렇게 만든 것인가 하는 것은 여전히 수수께끼로 남아 있다.' WHERE entry = 286;
UPDATE locales_page_text SET Text_loc1 = '이 연구의 이전 권에서의 뱀 숭배의 양상들, 나는 여기서 트롤들의 바다와의 흥미롭고 독특한 관계에 대해 조사했다. 그레이트 바닷가 그루 바시 제국은 바다의 3면에 둘러싸여 있었기 때문에 물이 사회의 한 측면으로 두드러지게 나타납니다. 트롤들이 정글 제국의 넓은 지역을 돌아 다니고 통제 할 수 있었지만, 바다는 그들을 벗어났습니다. 그것은 방대하고 헤아릴 수없는 것이 었습니다.' WHERE entry = 293;
UPDATE locales_page_text SET Text_loc1 = '줄구룹. 그래서 그 과정은 수세기 동안 계속되었고, 돌은 조수와 함께 나타 났고 조수는 조수로 떠났다. 현대의 \'조석의 돌\'이야기는 장소에 따라 등장했지만, 왜 그러한 권력의 대상이 그러한 규칙 성으로 왜 나타날 것이며, 누구의 디자인에 의해 등장해야하는지 궁금하게 여겨야한다.' WHERE entry = 302;
UPDATE locales_page_text SET Text_loc1 = '나는 내 부족과 내 집이 그리워. 평야의 바람이나 천둥 벼랑 위의 일몰을 기꺼이 환영합니다.나는 내게 멀지 않은 바다의 물을 볼 수 있지만 내 몸이나 기질을 식히는 데는 아무런 도움이되지 않습니다. 내 감옥에 대해서만 생각 나게한다.' WHERE entry = 310;
UPDATE locales_page_text SET Text_loc1 = '첫째 날: <br />오전 6:00~11:00 - 위쪽 야영지. <br />오전 11:00~11:30 - 휴식 및 점심 식사. <br />오전 11:30~오후 4:00 - 협곡 길.<br />오후 4:00~7:30 - 위쪽 야영지.<br /><br />둘째 날: 전날과 일정 동일.<br /><br />셋째 날: 동일 일정. <br /><br />넷째 날: 동일 일정. 단, 일몰 직전 토르센이 협곡 길로 내려가는 동안 자신을 엄호해 달라고 부탁했다. 우리 대원을 만나러 가는 길이라 생각했다. 그런데 그가 한 시간 후에 돌아왔다. 나는 그가 우리 대원을 만나 쿠르젠의 부대에 다시 합류하기를 기대했었기 때문에 놀랐다. 무언가 잘못된 것 같다.$B다섯째 날:<br />오늘은 토르센이 안절부절못하는 듯했다. 어제 나가 있는 동안 그가 무엇을 봤는지, 아니면 누구를 만났는지는 몰라도 아무튼 그때문에 그가 겁을 먹은 것이 분명하다. 나는 그가 우리 대원과 대화했을 거라고 생각했지만, 내가 엄호하는 동안 어디에 다녀왔는지 물어도 토르센은 아무 말도 하지 않았다. 그는 나를 친구라 믿고 위험한 비밀로부터 날 보호하려고 하는 것이다. 비록 나는 그의 그러한 신의를 받을 만한 자격이 없지만, 그는 무척이나 강한 신의를 보여 줬다. 그가 다시 우리와 뜻을 같이 하게 된다면 쿠르젠님의 군대에 큰 힘이 될 것이다.$B여섯째 날:<br />아침 일찍 토르센은 하사관 요화와 자세한 이야기를 나눴다. 난 아직 자고 있는 척해야만 했고, 따라서 엿들을 수 있는 거리로 움직일 수 없었다. 하지만 일전에 토르센이 나갔다 왔던 일에 대해 얘기했으리란 건 짐작할 수 있다.<br />점심 식사를 하면서 그를 유심히 살폈는데 요화도 나와 마찬가지로 그를 주시하고 있었다. 나중에 도렌이 토르센을 불렀다. 그들 세 명은 비밀을 공유하고 있는 것이다. 도렌과 요화는 토르센이 당신의 대원과 만나고 있다는 사실을 알고 있음이 분명하다. 그가 반역자들의 첩자 노릇을 하고 있는 것이다.$B이제 토르센에게 정보를 주어서는 안 되며 그를 처치해야 한다. 그는 대령님께 아무 쓸모도 없다.<br /><br />기회가 주어지면 바로 토르센을 처치하겠지만, 만약 당신이 이 편지를 받았다면 이는 내가 아직 기회를 잡지 못했음을 의미하는 것이다.<br /><br />그렇다면 다음에 토르센이 우리 대원과 만나는 때가 결정적인 기회일 것이다.<br /><br />쿠르젠 만세<br />- M' WHERE entry = 311;
UPDATE locales_page_text SET Text_loc1 = '못난 바보들!<br /><br />내 계획은 두 다리를 동시에 파괴하는 것이었다. 그런데 어리석은 네놈들은 어떻게 했느냐? 다리는 하나밖에 파괴하지 못했고 동맹 전체에 우리 계획만 알리는 꼴만 되지 않았느냐. 바보 같은 놈들!<br /><br />네놈들의 실수를 만회할 마지막 기회를 주겠다. 예비 폭탄을 아라시 고원의 다리에서 그리 멀지 않은 곳에 숨겨 두었다.<br /><br />네놈들의 임무를 완수하고 살아 있을 가치가 있다는 걸 증명하라!<br /><br />- 캄 딥퓨리' WHERE entry = 316;
UPDATE locales_page_text SET Text_loc1 = '저습지의 던 모드르에서<br /><br />사랑하는 사라에게,<br />수일 안으로 탄돌 교각을 감시하기 위해 이동해야 할 것 같소. 이것이 당신에게 보내는 마지막 편지가 될까 두렵소. 내가 이 세상에 존재하지 않게 되었을 때 당신이 내 소식이나마 알 수 있도록 이렇게 몇 줄 적어야겠다는 생각이 드는구려.$B이번 임무는 며칠 걸릴 것으로 보이는데 성공하면 아주 만족스러운 작전이 될 것 같소. 그리고 격전과 죽음이 도사리고 있을 거요. 하지만 내 기꺼이 얼라이언스를 위해 전장에서 쓰러질 각오가 되어 있소.<br /><br />우리가 추구하고 있는 대의에 대해 나는 한치의 의심도 없고 불안하지도 않을 만큼 내 용기와 믿음은 확고하다오.$B아이언포지 왕국이 얼라이언스의 승리에 거는 기대가 얼마나 큰지 알고 있소. 또 우리가 대전쟁에서 피를 흘리며 고통 속에 사라져 간 이들에게 얼마나 큰 빚을 지고 있는지도 잘 알고 있소. 나는 얼라이언스를 수호하고 그 빚을 갚기 위해 이 생에서 내 모든 기쁨을 기꺼이, 아주 기꺼이 희생할 각오가 되어 있소.$B사라, 당신을 향한 내 사랑은 영원할 것이오. 나를 감싸고 있는 강한 사랑의 끈은 오직 전능하신 신만이 끊을 수 있을 것이며, 왕국에 대한 내 충절은 강한 바람처럼 일어나 그 강한 사랑의 끈과 함께 전장에서 나를 굳건히 지탱시켜 주고 있소.$B당신과 함께 한 행복했던 모든 순간들의 기억이 내 머릿속을 스쳐 지나가는구려. 신과 당신, 오랫동안 나의 기쁨이었던 이 두 존재에 대해 너무나 깊이 감사하고 있소. 당신과 함께 살면서 서로 사랑을 나누고 우리 자식들 곁에서 훌륭한 드워프로 성장해 가는 모습을 지켜보게 될 미래에 대한 희망을 포기하고 불살라 버리는 것이 내게 얼마나 힘든 일인지 모를 거요.$B내가 감히 신의 섭리에 도전할 자격이 없다는 건 알지만, 누군가 내가 사랑하는 가족들에게 무사히 돌아가게 될 거라고 속삭이는 소리가 들리오. 어쩌면 공중에 떠다니는 우리 꼬마 에드거의 기도가 내게 전해진 것인지도 모르겠소. 사랑하는 사라, 내가 돌아가지 못하더라도 내가 당신을 얼마나 사랑하는지, 그리고 내가 전장에서 마지막 숨을 거두게 될 때 당신의 이름을 부를 것이라는 사실을 부디 잊지 말기 바라오.<br /><br />내가 저지른 많은 잘못과 당신에게 준 수많은 고통, 그리고 잦은 경솔함과 어리석음을 용서해 주시오.$B내 눈물로 당신의 행복을 막는 더러운 것들을 모두 씻어 내고 이 세상의 모든 악과 싸워 사랑하는 당신과 우리 자식들을 위험으로부터 지킬 수만 있다면 얼마나 기쁘겠소.<br /><br />하지만 그럴 수가 없구려.<br /><br />황천에 가서라도 반드시 당신을 지켜볼 거요. 그리고 당신이 이승에서 세파를 이겨내는 동안 그 곁을 지키며 기다리겠소. 우리가 다시 만나 영원히 함께하게 될 그 날까지...$B하지만 사라, 죽은 자들이 아제로스로 다시 돌아와 그들이 사랑했던 이들 주변을 몰래 맴돌 수 있다면, 나는 기쁜 날이나 슬픈 날이나, 칠흑 같이 깜깜한 밤이나 낮이나 언제나 당신 곁에 머무를 것이오. 당신의 볼에 부드러운 미풍이 분다면 그건 내 숨결일 것이며, 당신의 고동 치는 관자놀이에 서늘한 공기가 느껴진다면 그건 내 영혼이 당신 곁에 있기 때문일 거요. 사라, 내 죽음을 슬퍼하지 마시오. 나는 잠시 당신 곁을 떠나 당신을 기다리고 있다고 생각하시오. 우리는 반드시 다시 만날 테니까.<br /><br />설리' WHERE entry = 317;
UPDATE locales_page_text SET Text_loc1 = '나는 아이언 포지 왕국이 얼라이언스의 승리에 얼마나 강 력한 지, 그리고 대공전의 피와 고통을 통해 우리 앞에 놓인 사람들에게 얼마나 큰 빚을지고 있는지를 알고 있으며, 기꺼이 모든 것을 기꺼이 내려 놓고 있습니다. 이 동맹을 유지하고 그 빚을 갚을 수있는이 삶의 기쁨' WHERE entry = 319;
UPDATE locales_page_text SET Text_loc1 = '새라, 너를위한 내 사랑은 무의미 해. 전능 한 전선에서 나를 묶어주는 것 같아. 전능 외에는 아무것도 깨뜨릴 수없고, 왕국에 대한 나의 사랑이 나를 강풍처럼 휩싸이고, 모든 사슬을 전쟁터로 끌고 간다.' WHERE entry = 320;
UPDATE locales_page_text SET Text_loc1 = '내가 당신과 함께 보낸 행복한 순간의 추억이 내게 다가와서 빛과 당신에게 가장 깊은 감사를 느낀다. 나는 오랫동안 그들을 즐겁게 보았으며, 내가 그들을 포기하고 재로 타 오르기가 얼마나 힘든지 느낀다. 우리가 아직 살았을 때 함께 사랑하고 우리의 아들들이 우리 주변의 명예로운 왜소하게 자라 난 미래의 해가되기를 희망합니다.' WHERE entry = 321;
UPDATE locales_page_text SET Text_loc1 = '나는 신의 섭리에 대한 요구가 많지 않다는 것을 알고 있지만, 내게 속삭이는 어떤 것, 아마도 내 작은 에드거의기도가 될 것이다. 나는 사랑하는 사람들에게 무사히 돌아갈 것이다. 내가 사랑하지 않는다면 사라는 너를 얼마나 사랑하는지 결코 잊지 못할 것이다. 그리고 마지막 숨이 전장에서 나를 벗어날 때 나는 너의 이름을 속삭 일 것이다.$B$B 나는 너에게 많은 고통과 많은 잘못을 용서한다. 어리 석다 나는 종종 번 때가있다.' WHERE entry = 322;
UPDATE locales_page_text SET Text_loc1 = '당신의 행복에 조금이라도 눈물을 흘려서 당신과 당신의 사랑하는 자녀들을 해를 막을 수있는이 세상의 모든 불행과 싸우는 것이 얼마나 기쁠까요? $B 나는 할 수 없다. 우리가 더 이상 갈라 놓을 때까지 슬픈 인내심으로 기다리면서 당신의 소중한 작은화물로 폭풍우를 타파하면서 당신 가까이에 떠 다니며 떠돌아 다닙니다.' WHERE entry = 323;
UPDATE locales_page_text SET Text_loc1 = '바다에서 물기둥이 솟으며 넵툴로스는 지금은 멸망해 버린 이랄라이로 거대한 크라켄을 보냈다. 그들은 너무나 거대하여 그들의 지느러미에 의해 켈프의 밀림이 흔들리고, 그들 사이로 거대한 바다 생물들이 헤엄쳤다.<br /><br />그러면 가장 거대한 크라켄이 지느러미를 들어 그들을 모두 바다 속으로 처넣어 버리고 그의 주위로 파도를 만들어 보냈다. 그리고 그들은 이랄라이로 돌진했다.$B\\ud06c\\ub77c\\ucf04\\uc774 \\uc6b8\\ubd80\\uc9d6\\uc5c8\\ub2e4. \\ub188\\ub4e4\\uc758 \\ubaa9\\uc18c\\ub9ac\\ub294 \\ubc14\\ub2e4 \\ud3ed\\ud48d\\ucc98\\ub7fc \\ucc9c\\uc9c0\\ub97c \\uc6b8\\ub9ac\\uba70 \\uc774\\ub807\\uac8c \\uc678\\ucce4\\ub2e4.<br \\/><br \\/>\\$B<br /><br />민로스가 흔들림 없이 서서 마법을 불러일으켰다. 이랄라이로 향하던 파도가 갈라져 양쪽으로 휩쓸려 갔으며 그 너머에 있던 정글을 덮쳤다. 그리고 민로스가 그의 부하들에게 속박 주문을 시전하도록 명하자 수십 명의 트롤 목소리가 크게 울려 퍼졌다.<br /><br />그 중 한 음성이 유난히 크게 들렸다.$B민로스가 크게 소리치자 부하들이 읊은 주문의 힘이 그의 마법으로 한데 모여 접근해 오는 크라켄을 공격했다.<br /><br />바다가 갈라지고 민로스의 마법 주문이 넵툴로스의 부하들을 향해 돌진했다. 번개가 하늘을 가르며 마법 주문이 그들을 공격했고, 수천 개의 굵고 짧은 화살이 쏟아지며, 바닷물이 끓어오르고, 땅에는 불타는 분화구가 생겨났다.<br /><br />자신의 마법 주문이 거대한 짐승들을 쓰러뜨리리라 확신한 민로스는 승리의 함성을 외쳤다.$B하지만 크라켄은 오래, 아주 오랫동안 살아 왔다. 그들은 처음 바다에서 땅이 생겨나던 때를 기억하고 있었다.<br /><br />그들은 고대신들이 세상을 지배하고 여행자들이 나타나 마법으로 그들을 쓰러뜨리던 때를 기억했다. 그들은 처음으로 마법을 경험했던 때를 똑똑히 기억하고 있었다.<br /><br />그들은 오랜 세월을 살아왔으며 많은 비밀을 간직하고 있다. 비록 민로스의 마법 주문은 강했지만, 트롤과 마찬가지로 불멸의 것은 아니었기에 그의 마법은 실패하고 말았다.$B크라켄을 잡아 두는 데는 실패했지만, 그들의 주문은 놈들의 화를 돋우는 데 성공했다. 지금까지 필멸의 존재들 중에서 그들에게 고통을 준 상대는 없었으며, 트롤의 마법 주문은 그들에게 고통스러운 것이었다.<br /><br />그들은 민로스의 속박 주문을 벗어 버린 후 분노에 가득 차 울부짖었다. 깊은 곳에서 거대한 파도가 솟아올라 육지를 향해 돌진하면서 우레와 같은 소리가 들렸다. 파도가 이랄라이에 이르자 도시가 그 그림자에 덮였다.<br /><br />그러나 파도가 도시를 파괴하기 전에 크라켄은 공격을 멈추고 잠잠해졌다.$B트롤 의술사들은 떨면서 그들의 스승들에게 외쳤다. 민로스는 절망적이면서도 도전적으로 바다의 파도가 이루어낸 산맥을 쳐다보았다. 그가 그의 숙련된 부하들에게 몸을 돌려 속삭이자 트롤들이 그의 마지막 말을 돌에 새기고 민로스는 다가오는 크라켄을 향해 몸을 돌렸다.<br /><br />그는 얼굴을 찌푸리며 지팡이를 던졌다. 그것이 그의 용감한 마지막 저항이었다. 그러자 크라켄은 민로스에게 그들의 분노를 쏟아냈고 바다가 이랄라이를 덮쳤다. 그리고 이랄라이는 더 이상 존재하지 않게 되었다.$B그리고 바닷물이 정글을 덮쳐 모든 것을 깨끗이 쓸어버렸다. 바닷물이 덮쳐와 모든 것을 삼켜 버리자 트롤과 짐승들은 울부짖었다. 많은 구루바시 백성들은 바다가 자신들을 삼킨 이유를 궁금해 했지만 아무것도 알지 못한 채 모두 최후를 맞고 말았다.<br /><br />그리고 결국 바닷물은 산맥을 만나서야 멈췄다. 잠잠해진 바닷물은 죽음의 흔적을 남긴 채 해안 너머로 물러났다. 바닷물은 물러갔지만 이랄라이의 주위에서 굽이치며 그 땅을 영원히 수장되게 하였다.$B산맥 뒤편 줄구룹에서 무사할 수 있었던 족장 바르가줄은 정글로 나와 바닷물이 그의 동족을 휩쓸어 간 사실을 알게 되었다.<br /><br />그리고 그는 정복을 향한 그의 꿈이 좌절되었음에 절망했다.<br /><br />그리고 불뱀의 민로스는 영원히 찾아볼 수 없었다.' WHERE entry = 324;
UPDATE locales_page_text SET Text_loc1 = '내 명예로운 왕에게 :$B$B \'는 자신과 같은 훌륭한 지도자의 행동에 의문을 제기하는 병사의 아내가 아닌 곳입니다. 우리 땅을 가로 질러 분노한 전투는 우리가 알고 사랑하는 위대한 생명을 보존하기 위해 싸우고 있습니다. 모던의 시원한 물에서 던 모로의 활발하고 눈 덮인 봉우리에 이르기까지.' WHERE entry = 333;
UPDATE locales_page_text SET Text_loc1 = '그러나 우리가 보존의 이름으로 벌인 전쟁은 비용이 얼마나 드는가? 타락한 병사가 사망 한 후에 우리는 구원 받기 위해 노력하는 바로 그 생명이 전쟁터에서 우리를 빠져 나가는 것을 깨닫습니다.$B$B 우리는 우리의 미래를 얼마나 많이 던져야합니까? 우리가 과거에 묻어 야 할 부지의 토양은 몇 피트입니까?' WHERE entry = 334;
UPDATE locales_page_text SET Text_loc1 = '엘룬께서 내 소망을 들어 주셨다. 희생당한 우리 동료의 죽음은 결코 헛되지 않을 것이며 이 엘룬의 낫을 사용하여 내 손으로 복수를 이루고 말리라. 엘룬의 낫은 뒤틀리고 울퉁불퉁한 나뭇가지로 만들어진 고대의 유물로 칼도레이의 탄생 보다도 더 오래된 것 같다.<br /><br />한참 동안 여신께서 선사하신 이 도구를 살펴보았다. 이건 분명 보통의 무기가 아니고 단순한 마법 도구도 아니다. 이것만 가지면... 시공간을 넘나들 수 있다.$B낫을 손에 쥐자 혼란스러운 환영이 보였다. 늑대인간들... 그들이... 엄청난 적과 전투를 치르고 있었다. 늑대인간은 원시 종족답게 야만적으로 싸웠지만 그들의 적 에메랄드 불꽃의 지배자는 끄떡도 하지 않았다.<br /><br />그리고 그 순간 엘룬의 낫의 진정한 힘을 알게 되었다. 낫에 정신을 집중하자 오울겐과 의사 소통을 할 수 있게 되었던 것이다. 하지만 현실에서와 같은 대화를 통한 의사 소통은 아니었다. 뭔가 다른... 설명할 수 없는 어떤 수단을 통해서였다.$B중요한 것은 늑대인간들이 내 얘기를 듣고 이해할 수 있었다는 사실이다. 힘을 낫에 더 집중하자 현실과의 장벽이 약해졌고 늑대인간들을 우리 세계로 끌어들일 수 있었다. 첫 번째 시도에서 30명을 불러들였다. 그들은 나의 명령에 따라 전투에 참가해서 야만적인 힘을 발휘하며 악령의 숲의 악마들을 향해 돌진했다.<br /><br />엘룬께서 내 소원을 들어주신 것이다. 이제 숲은 정화될 것이다. 내 사명을 다할 때까지 엘룬의 축복이 나와 함께하기를...$B모든 것이 순조롭게 진행되고 있다. 함께 싸울 늑대인간을 더 많이 불러냈다. 그들은 단순하긴 했지만 놀라운 공격력과 결집력을 보여 줬다.<br /><br />그들 중에서 늑대 전사들을 작은 무리로 나눠 우두머리들 지휘권을 맡겼다. 우리는 숲의 여러 곳에서 동시에 공격을 수행하고 있고 내 작전은 효과적으로 악마들을 쓰러뜨렸다.<br /><br /><br />내 사명을 다할 때까지 엘룬의 축복이 함께 하기를...$B한 무리를 잃었다. 늑대인간 무리를 숲 멀리까지 보내 악마에게 점령된 지역을 파악하도록 했지만 그들은 돌아오지 않았다. 우두머리들에게 지휘권을 맡긴 것이 걱정되기 시작한다. 그들은 단순하기 때문에 작은 권력을 잡으면 최고의 지위까지 넘보려 할지 모른다. 이제 난 힘을 잃게 될 것이란 말인가? 당분간은 더 이상 늑대인간을 불러내지 말아야겠다.<br /><br /><br />내 사명을 다할 때까지 엘룬의 축복이 나와 함께 하기를...$B더 이상 늑대인간을 불러내지 않았음에도 불구하고 그 수가 계속 불어나고 있다. 마치 엘룬의 낫이 내 명령 없이도 스스로 그들을 불러낼 수 있게 된 것 같다. 큰 문제가 아닐 수 없다. 늑대 무리를 가능한 많이 모아 멜탄드리스의 제단에 남아 있을 것을 명했다.<br /><br />그 동안 다르나서스의 도서관들을 뒤지고 어둠의 해안 고대 의회에 조언을 구했다. 하지만 이 늑대인간들에 대해서 어떠한 정보도 찾지 못했다.$B키린토의 아루갈이라는 마법사에 대한 소문을 들었다. 그 역시 늑대인간을 불러냈을 가능성이 있다. 별로 내키지는 않지만, 이 마법사를 만나 그가 무엇을 알고 있는지 확인해야겠다.<br /><br />이 위험한 늑대인간들의 폭증을 막을 수 있기를 간절히 바란다. 그 다음 불모의 땅에 있는 항구로 가서 새로운 대륙으로 가는 배를 예약해야겠다.<br />내 사명을 다할 때까지 엘룬의 축복이 나와 함께 하기를...' WHERE entry = 396;
UPDATE locales_page_text SET Text_loc1 = '1. 1 인 또는 8 인$B$B2를 얻으십시오. 남자 하드$B$B3. 더 많은$B$B4 남자를 누르십시오. 사람을$B$B5에 불을 넣으십시오. 남자 먹어라.' WHERE entry = 410;
UPDATE locales_page_text SET Text_loc1 = '나즈 스팀보일이라는 고블린은 실제로 고블린 거상의 아들이다. 어느 거상인지를 밝혀내기 위해서는 큰 대가를 치러야 할 것이다.<br /><br />그는 직접 돈을 벌기보다는 자신의 가족이 번 돈을 쓰는 데 훨씬 더 관심이 많은 것 같다. 그래서 그는 가족이 저축해 둔 재산을 조금 훔쳐 지금은 소금 평원에 숨어 있다.<br /><br />그가 숨어 있는 곳을 그의 아버지가 알게 된다면 그를 찾아내 집으로 다시 끌고 갈 것이 분명하다. 오만한 행동에 대한 대가로 발가락 하나를 자른 채로 말이다.' WHERE entry = 438;
UPDATE locales_page_text SET Text_loc1 = '피즐버브씨,<br /><br />당신이 우리 동료에게 준 음료는 대단히 성공적이었소. 아주 강하고 정신을 몹시 흐리게 해줄 뿐만 아니라 중독성까지 있는 듯하군. 한 번 맛본 사람은 반드시 더 원하게 될 거요.<br /><br />당신에게 빚을 졌소이다, 크랭크.<br /><br />당신을 소금 평원에 초대하오. 아니면 믿을 만한 친구를 보내 이곳의 새로운 도박 기회를 놓치지 않기를 바라오.<br /><br />- 크레이블' WHERE entry = 440;
UPDATE locales_page_text SET Text_loc1 = '사람들을 자신의 의지 앞에 굴복시키는 데는 증오만큼 쉬운 수단이 없다는 사실에 항상 놀라곤 한다. 그 중에서도 오크와 트롤이 가장 쉬운 대상이다. 얼라이언스에 대한 증오로 그들은 암흑이교도의 말에 기꺼이 귀 기울이는 충성스러운 백성이 되었다. 자신들이 섬기는 더 큰 힘에 대해 조금이라도 알고 있을까? 격분한 성기사 수호자 델그렌이 잿빛 골짜기 숲에서 우리 일을 캐고 다니고 있고, 그의 부하 발툴은 내가 그의 존재를 모른다고 생각하며 우리 탑을 염탐하고 있다. 델그렌은 우리를 대수롭지 않게 생각하고 있다.$B아마 또 다른 죽음의 이교도 집단쯤으로 여기고 있을 것이다. 그는 우리가... 어둠의 의회의 이교도 중 하나에 불과하다는 사실을 거의 모르고 있다.<br /><br />내가 어린 아이였을 때, 겨우 알아볼 정도의 작은 점 크기의 파리처럼 보이지만 물리면 바로 죽을 수도 있는 곤충에 대한 이야기를 들은 적이 있다. 하지만 그 곤충은 물리면 살이 썩어 들어가며 매우 치명적인 해를 입힐 수 있으므로 박멸해야 한다.' WHERE entry = 443;
UPDATE locales_page_text SET Text_loc1 = '위협, 또 다른 죽음의 컬트, 아마도. 거의 우리는 우리가 암흑 협의회의 ... 가닥 중 하나라는 것을 알지 못합니다. 어렸을 때, 나는 한 번도 물기가 쉬운 곤충에 대해 이야기를 들었지만, 파리는 파리에 거의 못 미쳤다. 가장 해를 끼칠만한 일은 당신이 해고하는 일입니다.' WHERE entry = 444;
UPDATE locales_page_text SET Text_loc1 = '평생 동안 모든 인간이 할 수있는만큼 많은 양의 연구와 타이탄 제작자를 수행했습니다. 타이탄이이 세상을 떠날 때 다섯 가지 양상이있었습니다. 그들은 아제로스의 세계를 지키고 자하는 용사들이었습니다. 그들의 이야기는 방대하고 다양합니다. 심지어 지금까지 모아 놓은 모든 정보에도 불구하고, 나는이 장엄한 생물에 대해 더 많이 알게되었습니다.' WHERE entry = 447;
UPDATE locales_page_text SET Text_loc1 = '지금 가지고있는 지식의 대부분은 아마도 스스로 배울 수 없었을 것입니다. 이 때문에 나이트 엘프들에게 매우 감사드립니다. 그들의 도움으로 나는 내가하는 것만 큼 자세하게 설명했다.우리 상호 작용의 결과로, 나는 그들의 처음이 내가 처음 생각한 것보다 훨씬 더 밀접하게 묶여 있다는 인상을 받고있다. 그러나, 그들은 심지어 내가 알고 있기에 너무 밀접하게 비밀을 지키고 있습니다.' WHERE entry = 450;
UPDATE locales_page_text SET Text_loc1 = '나는 다른 사람들이 미래에 참조 할 수 있도록 여기에 담은 측면에 대해 배웠다. 시간이 지남에 따라이 용들이 우리 세계에 훨씬 더 큰 영향을 미칠 것이라고 생각하기 때문에 유용 할 것입니다.' WHERE entry = 451;
UPDATE locales_page_text SET Text_loc1 = '보호자로 여겨지는 청동 드래곤 플라이는 문명의 영역에 크게 매료됩니다. 드래곤과 그의 비행은 본질적으로 인내심이 강하며 항상 관찰에 의지하고 성급하게 행동하기 전에 계획대로 행동합니다. 노즈 도르 무는 더 큰 적에 의해 위협받을 때 항상 시간 흐름과 필멸의 종족을 보호하려고 시도합니다.' WHERE entry = 457;
UPDATE locales_page_text SET Text_loc1 = '검은 용은 완전한 변형을 겪었다.' WHERE entry = 459;
UPDATE locales_page_text SET Text_loc1 = '로데론에서 있었던 켈투자드의 성공으로 리치 왕은 인간 문명에 대한 공격을 감행하기 위한 최종 준비를 마쳤다. 그의 역병의 힘을 역병 가마솥이라는 이동 가능한 용기 여러 개에 담은 후, 넬쥴은 켈투자드에게 그 가마솥들을 로데론으로 수송하라고 명령했다. 그리고 그곳에서 이교도 집단이 장악한 여러 마을 안에 가마솥들을 숨겨 놓을 계획이었다.$B그러면 충성스러운 이교도들의 보호를 받은 가마솥은 전염병 생성기로 작동하게 되고 아무 것도 모르고 있던 로데론 북부의 농장과 도시들에 역병을 퍼뜨리게 되는 것이다.<br /><br />리치 왕의 계획은 완벽하게 성공하여 로데론 북부 마을들 중 다수가 거의 즉시 오염되었다. 노스렌드에서와 마찬가지로, 역병에 걸린 주민들은 죽음을 맞았고 그 후 리치 왕의 자발적인 노예로 되살아났다.$B켈투자드 수하의 이교도들은 기꺼이 죽기를 자처했고 어둠의 지배자의 충성스러운 신하로 다시 살아났다. 그들은 언데드로 불사의 몸이 될 수 있으리라는 희망에 기뻐 날뛰었다. 역병이 번지면서 북부 지역에 점점 더 많은 수의 죽음의 좀비들이 나타났다. 켈투자드는 점점 더 수가 불어나는 리치 왕의 군대를 지켜보며 \'스컬지\'라 이름 붙였다. 이는 곧 로데론 성문으로 진격하였는데 이는 이 세계에서 인류를 완전히 제거해 버릴 것이라는 의미를 담고 있었다.' WHERE entry = 572;
UPDATE locales_page_text SET Text_loc1 = '우주가 어떻게 시작되었는지 정확히 알지 못합니다. 어떤 사람들은 대격변적인 우주 폭발이 무한한 세계가 언젠가는 경이롭고 끔찍한 다양성을 지니고있는 거대한 암흑 세계의 광막으로 뻗어나 가게했다고 이론화했습니다. 다른 사람들은 존재하는 것처럼 우주가 단 하나의 전능 한 존재에 의해 전체적으로 창조되었다고 믿는다.' WHERE entry = 575;
UPDATE locales_page_text SET Text_loc1 = '자비로운 판테온은 구조화 된 세계를 보호하기 위해 비틀린 황무지의 사악하고 외형적인 존재로부터의 공격 위협에 항상 경계했습니다. 우주의 무수한 세계를 연결하는 혼란스러운 마법의 미묘한 차원 인 황천은 삶을 파괴하고 살아있는 우주의 에너지를 삼키려는 무한한 수의 악마 존재의 본거지였습니다.' WHERE entry = 578;
UPDATE locales_page_text SET Text_loc1 = '언약의 시작은 아제로스 왕자의 부패로부터 시작된 것이 아닙니다. 로데론의 몰락을 가져온 사건들은 그 시점 이전에 오랫동안 움직였습니다.그것은 오크 씨족과 불타는 군단의 출현으로 시작되었습니다.' WHERE entry = 669;
UPDATE locales_page_text SET Text_loc1 = '드레 노어의 오크들 (원래 그들이 온 세계)은 고귀하고 샤머니즘 적이었습니다. 그들은 강력한 전사 였고 몸과 의지가 강했습니다. 불타는 군단이 그들을 찾아낸 이유는 바로 이런 이유 때문입니다. 군단의 위대한 힘을 가진 악마 킬제덴은 오크 씨족을 노예화하고 불타는 군대가 아직 정복하지 못한 세계에 대항하여 군대로 사용하기를 원했습니다.' WHERE entry = 670;
UPDATE locales_page_text SET Text_loc1 = '킬제덴은 리치 왕을 신뢰하지 않았기 때문에 정신을 돌보고 리치 왕이 명령을 따르도록 두려운 영주를 보냈습니다. 뱀파이어 적 하인들은 리치 왕의 파괴와 권력과 행성 전체 종족의 대량 학살에 이끌려 기꺼이 아제로스에 왔습니다.' WHERE entry = 677;
UPDATE locales_page_text SET Text_loc1 = '10 년이 넘었습니다. 이시기에 리치 왕은 그의 거대한 힘을 사용하여 노스 렌드의 생물의 마음을 지배했습니다. 그는 노스 렌드의 얼어 붙은 왕위에 큰 성채를 세우라고 명령했습니다. 노스 렌드의 모든 것이 그의 지배하에 있었기 때문에 리치 왕은 로데론의 침투를 시작할 필요가 있음을 알았습니다. 얼음 속에 갇힌 오크 샤먼은 조작하고 통제 할 마음을 더 갖기 시작했습니다.그의 전화는 대륙을 가로 질러 도달했습니다.' WHERE entry = 678;
UPDATE locales_page_text SET Text_loc1 = '일기 - 일 512 바나나가 나에게 말하기 시작했고 나는 그들의 문화에 대해 많은 것을 배웠다. 나는 그들의 무의미한 가정 파괴와 젊은 세대의 소비를 중단했다. 내가 파괴하고있는 위대한 문명을 얼마나 알지 못했습니다. 다른 주제에 관해서 나는 병과 종이 위에서 낮게 달리고있는 것처럼 보인다. 내가 처음 해변에 닿았 던 거대한 종이 뭉치를 보았을 때 그들은 무진장 할 것이라고 생각했습니다. 내 일기는 곧 끝나야합니다.' WHERE entry = 697;
UPDATE locales_page_text SET Text_loc1 = '아제로스 대륙은 한없이 경이로운 땅이다. 그 대지 위에는 동식물과 문명, 그리고 마법이 충만하다. 사실, 호기심이 강한 이라면 누구나 이 대륙의 무한한 다양성을 깨닫게 될 것이다. 그냥 둘러보기만 해도 알 수 있으니 말이다.<br /><br />하지만 깊이 관찰하게 되면 완전히 새로운 세계의 창을 발견하게 될 것이며, 각각의 세계에는 저마다 경이로움이 기다리고 있다.<br /><br />각각의 세계에 저마다 공포가 숨어 있는 것처럼...$B이 책을 쓰는 목적은 우리 땅을 파괴하려고 하는 존재, 다른 세계의 악마들을 체계적으로 정리하여 그들과 마주치게 되는 모험가들에게 정보를 주기 위함이다.<br /><br />따라서 스스로 아제로스의 수호자라 여기는 이라면 이 책을 계속 읽기 바라며 적에 대해서 알게 되기를 바란다.<br /><br />- 우르<br />달라란 마술사$B늑대인간에 대해서<br /><br />시골에는 이 생물에 대한 오랜 전설이 전해져 오기 때문에 농부의 자손이라면 누구나 마을 밖의 숲과 늪을 어슬렁거리는 잔인한 늑대인간에 대해 들어 본 적이 있을 것이다.<br /><br />그리고 그런 전설에 진실이 숨어 있을지도 모른다. 우리를 겁주기 위해 신화처럼 베일에 가려진 채 전해오는 늑대인간에 대한 경고는 아닐까?$B하지만 그런 전설을 제쳐놓기 전에 독자들에게 한 가지 확실히 해 두어야겠다. 늑대인간은 실제로 존재한다. 우리 세계의 존재는 아닐지 몰라도 그들의 세계와 우리 세계를 연결하는 통로가 존재하며 강력한 마법을 사용해 그들을 이곳으로 불러올 수 있다.<br /><br />늑대인간은 지나는 곳마다 공포와 살육을 가져오기 때문에 그러한 주문은 언급하지 않는 것이 최선이다.$B늑대인간은 우리 세계의 늑대와 비슷한 외모를 가지고 있어 쉽게 알아볼 수 있다. 자세히 살펴보면 거친 털, 뾰족한 귀, 그리고 긴 주둥이에서 늑대인간은 우리가 아는 늑대와 유사하다는 사실을 알 수 있다.<br /><br />하지만, 차이점 역시 금방 눈에 띈다. 강인한 몸을 지탱하는 두 다리를 굵은 털이 뒤덮고 있으며, 긴 송곳니와 칼처럼 날카로운 발톱이 두드러져 보인다. 그리고 그 울음소리 뒤에는 자연의 짐승에게는 찾아볼 수 없는 증오가 숨어 있다.$B늑대인간의 고향은 악몽이 가득한 장소인 어둠의 땅이다. 만약 그 세계에 저주받은 늑대인간으로부터 안전한 곳이 있다면 내 연구를 통해서는 아직 그런 요새를 알아 내지 못했다. 그리고 늑대인간의 잔인함과 사악한 면으로 미루어 볼 때 그런 곳은 존재하지 않을 가능성이 크다.<br /><br />일부 늑대인간은 강력한 마법을 지니고 있으면서도 스스로 아제로스에 들어오려는 시도를 하지 않은 것으로 보아 자신들의 세계에 머무르는 데 만족하는 것 같다. 그리고 그 점이 우리로서는 다행이 아닐 수 없다.$B위에서 언급했듯이, 일부 늑대인간들은 신비로운 기술을 사용하는 데 능숙하며 그들이 사용하는 마법은 어둠과 타락의 마법이다.<br /><br />보통 저주와 초자연적인 독약을 사용하므로 주의해야 한다. 즉, 늑대인간 마법사를 상대하는 이들은 어둠을 상대할 수 있는 방어 태세를 갖추어야 한다.$B정의로운 마음을 가진 자의 양심에 의해서라도 달라란 마술사가 늑대인간을 찾는 일이 일어나지 않기를 바란다. 이 짐승과는 어떠한 계약도 맺을 수 없으며, 어떠한 비밀도 알아낼 수 없고, 아무런 이득도 얻을 수 없기 때문이다.<br /><br />늑대인간은 그들의 세계에 있도록 두는 것이 가장 좋다. 그들이 우리 세계에 나타나고 누구도 그들을 처치하지 못한다면 우리에게 끔찍한 위험이 닥치게 될 것이기 때문이다.' WHERE entry = 698;
UPDATE locales_page_text SET Text_loc1 = '오래된 신들은 우리 세계의 의지입니다. 폭풍이 몰아 치는 곳마다 오래된 신의 웃음 소리가 들립니다. 산불의 불길은 그들의 시선의 열기입니다.오래된 신이 걷는 동안, 지구는 떨리고 끊어지고, 적은 것들이 절망 속에서 자신의 육체로 비명을 지르며 찢어집니다. 그리고 절망에 빠져들어야합니다. 불의 어린 아이가 호기심을 느끼지 않는 것처럼, 늙은 신들도 그 아래에있는 사람들을 돌보지 않습니다. 기껏해야, 우리는 졸입니다. 최악의 경우, 우리는 장난입니다.' WHERE entry = 795;
UPDATE locales_page_text SET Text_loc1 = '그들은 세계의 첫번째 주인이었고, 그들은 힘과 공포로 통치했습니다. 그들은 지금 사슬에 묶여 있고 자고 있지만, 그들의 하인들은 여전히 ​​배회하고 우리는 작습니다. 약한 필사자들은 그들의 힘을 일치시킬 수 없습니다.$B$B시도하는 사람은 먹었습니다. 그러나 자신의 위치를 ​​아는 사람들, 오래된 신들의 종들에게 간청하면서 무릎을 꿇고 기꺼이 마음과 영혼을 희생하는 사람들은 오직 은혜를 얻습니다.' WHERE entry = 796;
UPDATE locales_page_text SET Text_loc1 = '벤처 기업 <읽을 수없는 텍스트> 혼합물을 안정화시키기 위해 바보들이 전체 작업을 거의 지워 버린 것처럼 보일 것입니다.$B$B <여러 페이지가 찢어진 것으로 보입니다>$B$B' WHERE entry = 1151;
UPDATE locales_page_text SET Text_loc1 = '내가 알아 차린 것은 낙진이 치명적이라는 것입니다. <읽을 수없는 텍스트> 하하하라고 상상해보십시오!' WHERE entry = 1152;
UPDATE locales_page_text SET Text_loc1 = '커글,<br /><br />그대의 새로운 발명품을 몹시 기다리고 있답니다. 어서 빨리 그 발명품을 사용해서 내 연구에 대해 기록하고 싶군요.<br /><br />심부름꾼을 보낼 테니 그에게 맡겨주세요.<br /><br />고마워요.<br /><br />다린 라이트윈드' WHERE entry = 1156;
UPDATE locales_page_text SET Text_loc1 = '이 정보를 적의 손에 넣지 마십시오! 01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101101 01100101 00100000 01101011 01100101 00100000 01101011 01101001 01101110 01100101 00100000 01110111 01100101 01100001 0111010 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010' WHERE entry = 1192;
UPDATE locales_page_text SET Text_loc1 = '보안 등급 10 ^ 10000의 매우 민감한 데이터!01001000 01100101 01101100 01110000 00100001 00100000 00100000 01001001 00100111 01101101 00100000 01110100 01110010 01100001 01110000 01110000 01100101 01100100 00100000 01101001 01101110 00100000 01100001 00100000 01100010 01101001 01101110 01100001 01110010 01111001 00100000 01110000 01110101 01101110 01100011 01101000 00100000 01100011 01100001 01110010 01100100 00100000 01100110 01100001 01100011 01110100 01101111 01110010 01111001 00100001' WHERE entry = 1193;
UPDATE locales_page_text SET Text_loc1 = '본 무훈의 증서는 &lt;name&gt;|1이;가; 이글거리는 협곡의 스컬지, 난폭한 마르골을 처치했음을 증명하기 위한 것이다.<br /><br />아이언포지 박물관은 이 업적을 인정하며 본 증서 지참인의 관대한 공헌에 대해 감사를 표하는 바이다.<br /><br />- 도서관장 소리우스 스톤텐더' WHERE entry = 1231;
UPDATE locales_page_text SET Text_loc1 = '기계공학<br /><br />아제로스에서 누가 기계공학이란 학문을 먼저 만들어 냈는지는 분명치 않으나, 현대에 와서 노움과 고블린이 기계공학을 제창했다는 사실은 반론의 여지가 없다. 기계공학에 대한 그들의 헌신으로 발명의 시대라고 칭할 만한 이 시대에 아주 훌륭한 발명품이 탄생했다. 그들 종족 간에는 경쟁이 매우 치열했다. 이러한 경쟁은 기계공학의 각 분야에서 두드러진다.$B노움 기계공학<br /><br />노움은 전체적으로 주변의 세계를 조작 및 제어하는 장치의 설계에서 탁월한 기술을 선보인다. 폭발물과 무기의 개념에 대한 이해는 피상적인 수준에 그치고 있지만, 대신 노움 기계공학은 말 그대로 삶을 보다 편리하고 쉽게 만드는 장치에 중점을 두고 있다. 이 학문은 이론적인 가능성이 노움의 전문적 지식을 통해 현실화되는 것을 다루는 것이다. 그러나 일부 가능성은 결코 완전하게 현실화되지 못한다.$B고블린 기계공학<br /><br />스스로 거의 모든 분쟁에서 중립적이라고 생각하는 고블린 종족은 과학을 이익으로 전환하기 위해 아주 대단한 조치를 취했다. 기계공학의 실질적인 응용 노선을 채택한 이들의 관점은 폭발물, 화기, 기계 장치 등의 급진적인 설계에서 분명하게 드러난다. 고블린 기계공학은 기계공학의 이론을 크게 중요시하지 않는다. 일반적으로, 그들의 발명품이 제대로 작동하지 않는 일은 없고 오히려 작동을 너무 잘해서 문제가 된다. 심장이 약한 사람은 절대 손을 대서는 안 될 학문이다.$B분과 학문 연구<br /><br />노움과 고블린은 서로에게 자신들의 지식을 공개하지 않기 때문에 두 가지 학문을 동시에 배우는 것은 불가능하다. 각 종족은 정치적 소속에 상관없이 상대 종족의 학문 추구를 포기하는 것에 동의하는 자들에게만 자신들의 학문을 가르친다. 예를 들어, 어떤 학생이 노움 기계공학을 추구하기로 결정하면 이 학생은 고블린 기계공학을 배울 수 없게 된다.$B영구적 결정<br /><br />두 가지 기계공학 분야에 대해 앞에서 지적한 중요한 사항은 교육을 위해 다시 한번 짚고 넘어가야 한다. 이 두 학문 중 하나를 선택하는 것은 다른 학문을 결코 공부할 수 없게 되는 것을 뜻하며, 이러한 최종성은 비전문 기술자의 기를 꺾을지도 모르나 노련한 기술자는 노움과 고블린이 자신들의 비밀을 철저하게 보호하는 것을 이해하게 된다. 아무것도 배우지 않는 것보다는 일부라도 배우는 것이 낫다.$B\\uc778\\uc6a9\\ubb38<br \\/><br \\/>\\$B<br \\/>-- \\ub178\\uc6c0 \\uae30\\uc220\\uc790, \\ub9c1\\uace0 \\ud2b8\\ub798\\uc9c0\\ub515\\uc158<br \\/><br \\/>\\$B<br />-- 고블린 포병, 야즈 니트로스포크$B\\ucd94\\uac00 \\uc778\\uc6a9\\ubb38!<br \\/><br \\/>\\$B<br \\/>-- \\uae30\\uc220\\uc790 \\uc870\\ud569\\uc7a5, \\ub2c9\\uc2a4 \\uc2a4\\ud504\\ub85c\\ucf13\\uc2a4\\ud504\\ub9c1<br \\/><br \\/>\\$B<br />-- 노움 발명가, 로비스 맥크랭큰스팽크' WHERE entry = 1271;
UPDATE locales_page_text SET Text_loc1 = '영구 결정$B$B 이전 절에서는 교육을 위해 반복해야하는 두 가지 공학 분야에 관한 중요한 점을 강조했습니다. 두 분야 중 하나에 종사하기로 결정하면 반대하는 분야의 구성표를 연구에 사용할 수 없습니다. 이러한 최종성은 평신도 엔지니어에게 위협적 일 수 있지만 노련한 사람은 놈들과 고블린들이 완전한 열정으로 자신의 비밀을 지키고 있음을 이해합니다. 어떤 지식은 항상 어떤 것보다 낫다.' WHERE entry = 1275;
UPDATE locales_page_text SET Text_loc1 = '쪽지를 주은 자에게<br /><br />이 쪽지를 읽고 있다면 당신은 다음 두 장소 중 하나에 있는 것이다.<br /><br />1. 아즈샤라의 남부 반도.<br /><br />2. 절벽거인의 뱃속<br /><br />둘 다 편히 쉴만한 곳은 못 된다.<br /><br />나도 한때 남부 반도에도 있어 보았고 지금은 뱃속에 앉아 이 쪽지를 쓰고 있다.$B거인의 뱃속에 있으면 생각할 시간이 생기게 된다.<br /><br />내 몸이 결정화되어 가면서 나도 어쩌면 아직도 이 세상에 많은 영웅 중 하나가 나를 구할 수 있을지도 모른다는 희망을 품게 되었다. 내 어떻게든 이 곤경을 벗어나게 되면 그 유령 같은 오크 녀석의 목을 졸라 버리고 싶다!<br /><br />- 윈던 셰이' WHERE entry = 1311;
UPDATE locales_page_text SET Text_loc1 = '거인의 뱃속에있는 것은 반성을위한 한 번을 준다.제 몸이 결정되면서, 나는이 세상에 충분한 영웅이 있다고 결론을 내 렸습니다. 나는 어떻게 든이 곤경에서 벗어나서 그 오크의 유령 목을 울릴 것입니다! - 윈난 셰이' WHERE entry = 1312;
UPDATE locales_page_text SET Text_loc1 = '내가 지금 무슨 생각을 하고 있는 것일까?<br /><br />좀 더 나은 질문이 되려면 이렇게 물어야 할 것이다. 거인의 뱃속에 들어앉아서 쪽지나 쓰고 있다니 이게 무슨 짓일까?<br /><br />둘 다 내가 지금 당장 답할 수 없는 질문들이다...<br /><br />사실, 내가 여기로 오게 된 이유 자체부터 어리석었다. 아즈샤라 남부에서만 나는 수정, 아즈샤리트를 찾아 온 것이다. 아, 그것만 손에 넣었다면 엄청난 부자가 되었을 것을!<br /><br />나, 참! 지금 내 꼴을 보라고...$B\\uc774\\uc131\\uc801\\uc778 \\uc874\\uc7ac\\uac00 \\uc774 \\ucabd\\uc9c0\\ub97c \\ubc1c\\uacac\\ud55c\\ub2e4\\uba74 \\uc2a4\\uc2a4\\ub85c\\uc5d0\\uac8c \\uc9c8\\ubb38\\uc744 \\ub358\\uc838 \\ubd10\\uc57c \\ud560 \\uac83\\uc774\\ub2e4. \\$B라고.<br /><br />- 무크' WHERE entry = 1313;
UPDATE locales_page_text SET Text_loc1 = '솔로몬,<br /><br />이 명령서를 지닌 자는 스톰윈드의 부관 대리로 공식 임명되었노라. 그러니 이 자를 보내 검은용군단이 검은바위부족 오크와 연루되어 있다는 증거를 찾도록 하라. 증거를 찾거든 이 부관이 스톰윈드에 있는 내게 그 증거를 보낼 것이다. 그 증거를 받으면 레이크샤이어에 지원 병력을 투입하는 명령을 허가하겠노라.<br /><br />대영주 볼바르 폴드라곤' WHERE entry = 1471;
UPDATE locales_page_text SET Text_loc1 = '안녕하세요. 모험가 여러분!<br /><br />저, 크린클 굿스틸은 험난한 임무를 수행하기 위해 기꺼이 위험을 무릅쓸 뜻이 있는 분들을 찾고 있습니다. 제가 책임지고 있는 임무와 작업량이 너무 많은 이유로 이 목록에 적힌 물건들을 제게 무사히 가지고 오시는 분에게는 후한 사례를 하겠습니다.<br /><br />물건 목록은 다음 페이지에 있습니다...$B단단한 수정 다리 마디 - <br /><br />믿을 수 없겠지만 이글거리는 협곡에 서식하는 유리그물거미는 수정 같은 물질로 이루어져 있습니다. 이 거미들을 처치할 때 다리가 손상되지 않게 해서 가지고 오시면 제 동료들의 기계공학 실험에 아주 우수한 도체로 사용할 수 있을 겁니다.<br /><br />실험해 볼 다리가 좀 필요한데 거미에게는 다리가 8개나 있으니까 강인한 전사나 솜씨 좋은 마법사에게는 문제가 되지 않을 것입니다.$B부쳐지지 않은 소포 - <br /><br />믿을 만하다고 생각한 조종사 하나를 고용해 테라모어에서 소포 하나를 가져오게 했었는데 생각보다 실력이 아주 형편없었습니다. 그 조종사가 살아서 자초지종을 듣긴 했지만 자기 목숨 건지려고 비행선과 화물을 몽땅 버려두고 와버렸지 뭡니까.<br /><br />그 소포가 필요합니다. 비질 말로는 그 자가 먼지진흙 습지대 만의 바로 서쪽에 추락했다고 해요. 물가에 있는 언덕을 넘자마자 바로 추락했다더군요.<br /><br />음... 그런데 추락한 원인은 말해주지 않았습니다.$B균형 잡힌 굿스틸의 플랑베르주 - <br /><br />마지막으로 찾아야 할 물건은 제가 지금까지 대장장이로 살면서 만든 물건 중 가장 우수한 것입니다. 이 플랑베르주는 믿을 수 없을 만큼 훌륭한 검이었는데, 저는 이 검을 명예롭고 위대한 전사라고 생각된 자에게 주었습니다. 그런데 그만 그 전사가 자르콰이인가 하는 멀록에게 당하고 말았지요.<br /><br />그 전사는 슬픔의 늪 해안을 따라가던 중 멀록을 공격했었습니다. 하지만 멀록에게 당한 전사는 도망을 치다 그 검을 버렸고 결국 멀록이 가져가 버렸습니다.$B물건들을 찾거든 이 장부와 함께 가젯잔으로 가지고 와주세요. 그러면 사례를 하겠습니다.' WHERE entry = 1551;
UPDATE locales_page_text SET Text_loc1 = '이 장부를 찾은 다음,이 장부와 함께이 품목들을 모두 찾아 가제트로 돌아가십시오. 그러면 나는 당신에게 보상 할 것입니다.' WHERE entry = 1556;
UPDATE locales_page_text SET Text_loc1 = '&lt;페이지마다 고대 엘프의 룬문자가 가득합니다.&gt;<br /><br />본 서적은 하급 영약을 제조하는 데 필요한 재료를 수집하고 제작하는 과정에서 일어난 사건들에 대한 기억을 담고 있다.<br /><br />부디 이 책이 적들의 손에 들어가지 않기를.<br /><br />부디 살아서 다시 한번 쿠엘탈라스에 창백한 달빛이 비치는 광경을 볼 수 있기를.<br /><br />부디 캘타스님의 은총 속에서 숨을 거두기를.<br /><br />부디 일리단님의 영광을 위해 살생도 불사하기를.<br /><br />-카리엘 윈탈루스$B<img src=\\$B />$B<img src=\\$B />$B<img src=\\$B />$B<img src=\\$B />' WHERE entry = 1631;
UPDATE locales_page_text SET Text_loc1 = '나타카, 버섯구름 봉우리에선 모두 무사하오. 켄타우로스가 가끔씩 공격을 해와 성가시긴 하지만 실제로 위협적인 것은 아니고 말 그대로 성가신 것 뿐이오. 하지만 켄타우로스 부족이 결합하고 있다는 소문이 들리는 듯하오.<br /><br />우리는 항상 켄타우로스처럼 무자비한 종족이 단결하면 어떤 위협이 될까 궁금했는데... 그런 생각은 될 수 있으면 하고 싶지 않소. 알다시피 그 어떤 것도 녀석들이 가진 순수한 증오를 뚫을 수는 없소. 서로에 대한 증오까지도 말이오.<br /><br />- 절벽파수꾼 롱혼' WHERE entry = 2271;
UPDATE locales_page_text SET Text_loc1 = '다로우샤이어 연대기<br /><br />서쪽의 다로미어 호수에서 그 이름이 유래한 다로우샤이어는 로데론의 남쪽 구릉지 안쪽에 위치한 마을이다. 다로우샤이어는 보잘것없지만 주민들이 근면하기로 소문이 자자하며 2차 대전쟁 이전에는 로데론 역사의 뒷전에 머물러 왔을 뿐이다.<br /><br />그 전쟁 중 많은 영웅들이 탄생했고 사라져 갔다.$B다로우샤이어 전투<br /><br />다로우샤이어 전투는 스컬지 병력이 로데론을 쑥대밭으로 만든 2차 대전쟁이 한창 벌어지고 있던 도중 일어났다. 다로우샤이어는 대부분의 얼라이언스 병력과 단절되었지만 은빛 성기사단의 파견대와 경비대장 조셉 레드패스가 이끄는 든든한 민병대원이 마을을 지켜 주었다.$B스컬지는 다로우샤이어에 산발적인 첫 공격을 시작했다. 소규모의 해골 부대와 좀비들이 습격하며 마을 외곽을 배회하며 습격하였지만 결국 격퇴되었다.<br /><br />그러나 스컬지는 병사들의 완강한 저항에도 주저하지 않고 첫 번째 공격을 한 지 얼마 지나지 않아 두 번째 공격을 해왔다. 놀 군주 호르구스의 부하인 놀 용사들이 소리를 지르며 언덕을 내려와 포위된 다로우샤이어의 병사들과 격돌했다.$B민병대원들은 약해졌지만 은빛 성기사단의 성기사들이 구원이 되었다. 다로우샤이어 출신인 그들의 지도자 다빌 크록포드가 임박한 공격 소식에 추종자들을 데려와 병사들과 함께 호르구스의 부하들을 저지했다.<br /><br />마침내 호르구스가 직접 전투에 참가했을 때 그는 다빌과 맞닥뜨렸다. 장시간의 격투 끝에 마침내 다빌이 승리를 거두었지만 치명적인 부상을 입어 놀 군주를 굴복시킨 후 곧 죽음을 맞이하게 되었다.$B전투는 계속되었고 경비대장 조셉 레드패스는 그의 민병대를 용감하게 이끌었다. 죽음의 기사 검은 마르두크가 경비대장을 타락시키지 않았더라면 전쟁에서 승리했을지도 모른다.<br /><br />격투 중 마르두크가 말을 타고 레드패스에게 접근하여 흑마법으로 레드패스의 영혼을 끌어내서 용감한 경비대장을 사악한 어둠의 존재로 만들었다.$B타락한 경비대장 레드패스는 그의 타락한 영혼을 다로우샤이어의 병사들에게 퍼뜨려 동지들을 배신하고 학살하게 하였다. 그 후 그들은 집에 숨어 있던 다로우샤이어 주민들을 모두 학살했다.<br /><br />남은 스컬지 군대는 타락한 경비대장 레드패스의 영혼과 함께 참혹하게 유린당한 다로우샤이어 마을을 떠난 후 로데론으로 쳐들어가 2차 대전쟁에 더 많은 고통과 죽음을 안겨 주었다.' WHERE entry = 2371;
UPDATE locales_page_text SET Text_loc1 = '다로우샤이어 연대기<br /><br />서쪽의 다로미어 호수에서 그 이름이 유래한 다로우샤이어는 로데론의 남쪽 구릉지 안쪽에 위치한 마을이다. 다로우샤이어는 보잘것없지만 주민들이 근면하기로 소문이 자자하며 2차 대전쟁 이전에는 로데론 역사의 뒷전에 머물러 왔을 뿐이다.<br /><br />그 전쟁 중 많은 영웅들이 탄생했고 사라져 갔다.$B다로우샤이어 전투<br /><br />다로우샤이어 전투는 스컬지 병력이 로데론을 쑥대밭으로 만든 2차 대전쟁이 한창 벌어지고 있던 도중 일어났다. 다로우샤이어는 대부분의 얼라이언스 병력과 단절되었지만 은빛 성기사단의 파견대와 경비대장 조셉 레드패스가 이끄는 든든한 민병대원이 마을을 지켜 주었다.$B스컬지는 다로우샤이어에 산발적인 첫 공격을 시작했다. 소규모의 해골 부대와 좀비들이 습격하며 마을 외곽을 배회하다 격퇴되었다.<br /><br />그러나 스컬지는 병사들의 완강한 저항에도 주저하지 않고 첫 번째 공격을 한 지 얼마 지나지 않아 두 번째 공격을 해왔다. 놀 군주 호르구스의 부하인 놀 용사들이 소리를 지르며 언덕을 내려와 포위된 다로우샤이어의 병사들과 격돌했다.$B민병대원들은 약해졌지만 은빛 성기사단의 성기사들이 구원이 되었다. 다로우샤이어 출신인 그들의 지도자 다빌 크록포드가 임박한 공격 소식에 추종자들을 데려와 병사들과 함께 호르구스의 부하들을 저지했다.<br /><br />마침내 호르구스가 직접 전투에 참가했을 때 그는 다빌과 맞닥뜨렸다. 장시간의 격투 끝에 마침내 다빌이 승리를 거두었지만 치명적인 부상을 입어 놀 군주를 굴복시킨 후 곧 죽음을 맞이하게 되었다.$B전투는 계속되었고 경비대장 조셉 레드패스는 그의 민병대를 용감하게 이끌었다. 죽음의 기사 검은 마르두크가 경비대장을 타락시키지 않았더라면 전쟁에서 승리했을지도 모른다.<br /><br />격투 중 마르두크가 말을 타고 레드패스에게 접근하여 흑마법으로 레드패스의 영혼을 끌어내서 용감한 경비대장을 사악한 어둠의 존재로 만들었다.$B타락한 경비대장 레드패스는 타락한 영혼을 다로우샤이어의 병사들에게 퍼뜨려 동지들을 배신하고 학살하게 만들었다.  그 후 그들은 집에 숨어 있던 다로우샤이어 주민들을 모두 학살했다.<br /><br />남은 스컬지 군대는 타락한 경비대장 레드패스의 영혼과 함께 참혹하게 유린된 다로우샤이어 마을을 떠난 후 로데론으로 쳐들어가 2차 대전쟁에 더 많은 고통과 죽음을 안겨 주었다.$B약탈자 호르구스의 운명<br /><br />약탈자 호르구스는 다로우샤이어 전투에서 패배했지만 그가 지니고 있던 사악함은 완전히 사라지지 않았다. 승리한 스컬지 병력은 다로우샤이어의 전쟁터에서 그의 머리를 가져다가 살아있는 자들과 마주칠 때마다 그들에게 공포감을 심어 주었다.<br /><br />며칠 후 호르구스의 머리를 가지고 있던 스컬지 일당은 은빛 성기사단에 패배했고 호르구스의 머리는 검은나무 호수에 버려졌다.$B검은 마르두크의 운명<br /><br />마르두크는 2차 대전쟁에서 살아남아 룬이 박힌 사악한 검으로 많은 이들을 고통과 죽음으로 내몰았다. 마르덕은 여전히 살아 있지만 코린 삼거리 근처에서 일어난 전투에서 그 검을 잃게 되었다. 드워프 대장이 마법의 방패로 그의 검을 산산조각내어 마르두크를 몰아냈고 결국 얼라이언스에게 승리를 안겨 주었다.<br /><br />마르두크의 검은 땅 밑으로 가라앉아 협곡을 빨아들이며 대지를 오염시켰고 현재의 오염의 흉터가 생기게 되었다.$B다빌 라이트포지의 운명<br /><br />다빌 라이트포지는 다로우샤이어 전투에서 사망했지만 그의 용기는 전쟁기간 동안 얼라이언스를 고무시키기에 충분했다.<br /><br />한편 그가 쓴 책인 성기사의 성서가 붉은십자군에 의해 발견되었다. 현재 붉은십자군이 지배하는 하스글렌의 마을 회관에 보관되어 있으며 다빌의 힘을 본받으려는 십자군들이 종종 이 책을 읽기도 한다.$B조셉 레드패스의 운명<br /><br />조셉 레드패스는 다로우샤이어 전투에서 사망했다. 그의 영혼은 타락하여 새로운 모습으로 태어났고 로데론에 가공할 악을 퍼뜨렸다.<br /><br />타락한 레드패스는 안돌할의 동쪽에 있는 가론의 흉가에서 마침내 얼라이언스에 패배했다. 그의 방패는 아직도 역병 걸린 농장에 있으며 스컬지의 앞잡이들은 여전히 그의 사악함에 대한 기억에 이끌리곤 한다.$B카를린 레드패스의 운명<br /><br />경비대장 조셉 레드패스의 형제인 카를린은 다로우샤이어 전투에서 패배했다. 카를린은 심한 부상을 입었지만 죽지는 않았다.<br /><br />전투가 끝나고 며칠 후 은빛 여명회의 대원들이 코린 삼거리 근처에서 갈증과 열병으로 약해진 채 방황하고 있던 카를린을 발견하여 카를린을 치료하고 희망의 빛 예배당으로 데려갔다.<br /><br />그들의 자비에 감사하며 카를린은 은빛 여명회에 합류했고 이제 스컬지에 대항해 복수의 전투를 치르고 있다.' WHERE entry = 2377;
UPDATE locales_page_text SET Text_loc1 = '작성일: 알 수 없음<br /><br />성명: 나타노스 매리스, 로데론의 인간 순찰대장.<br /><br />내용:<br />나타노스 매리스를 순찰대로 불러들이는 것에 대한 본인의 결정에 캘타스 선스트라이더가 이견을 가졌음을 기록하는 바이다. 아울러 나타노스는 인간임에도 불구하고 내가 가르친 순찰대원 중 가장 뛰어난 자였다는 사실 또한 기록한다.<br /><br />(계속)$B우리는 수천 년 동안 외부와 단절된 채 지내왔다. 우리가 과거에 저지른 일에 대해서는 내가 가장 먼저 인정하는 바이다. 애초에 인간들에게 마법을 가르쳐주어서는 안 되는 것이었다. 이 사실을 부인하지는 않겠지만, 선조들의 실수로 인해 우리가 이렇게 억압된 환경 속에서 지낼 수는 없다. 쿠엘도레이와 이 세계의 타 종족들이 공생한다면 많은 일을 해낼 수 있으니 우리는 인내를 배워야만 한다.<br /><br />(계속)$B이런 이유로 나타노스 매리스에 대한 캘의 요청을 거부하는 바이다. 나타노스는 아주 귀중한 동료가 될 테니 내 말을 새겨들어라.<br /><br />서명,<br /><br />실바나스 윈드러너<br /><br />실버문의 순찰대 사령관' WHERE entry = 2431;
UPDATE locales_page_text SET Text_loc1 = '이 3 페이지 문서는 비어 있습니다.' WHERE entry = 2531;
UPDATE locales_page_text SET Text_loc1 = '부적에는 5 개의 보석이 없습니다. 그리고 그 보석들이 발견되어 상징으로 다시 자리 잡으면 그 힘은 현재의 형태보다 훨씬 커질 것입니다. 나는 5 개의 보석을 발견했지만, 그것을 수집하는 데 도움이 될 당신의 기술 중 하나가 필요합니다.살해 무명의 선지자는 그의 이단을 훔치는 것과 마찬가지로 확실한 이단이며, 내가 다음에 너에게 물어 보는 것은 켄타 우르가 그것을 생각조차하지 않을 것이라고 비난 할 것이다.' WHERE entry = 2593;
UPDATE locales_page_text SET Text_loc1 = '영의 부적의 힘을 사용하여 그 (것)들에게서 명예와 주옥을 가지고 가도록 강요하십시오! 후에 보석을 영혼 부적에 넣고 돌려 보내십시오. 내가 부적 부적을 얻은 후에 나는 종족을 개혁 할 수있을만큼 충분히 강해 져서 마침내 조상들이 우리가되기를 원했던 것처럼 될 수 있습니다!' WHERE entry = 2596;
UPDATE locales_page_text SET Text_loc1 = '<이 페이지에 쓰여진 내용은 이해할 수 없습니다.>' WHERE entry = 2632;
UPDATE locales_page_text SET Text_loc1 = '<잉크가 소용돌이 치며 페이지 주위로 이동합니다. 당신은 책이 당신을 조롱하고 있다는 느낌을 갖습니다.>' WHERE entry = 2634;
UPDATE locales_page_text SET Text_loc1 = '그의 이름은 빛을 가장 어둡게 만든 아제로스를 가져왔다.$B$B그의 허물은 잘못된 길의 벽을 무너 뜨렸다.$B$B은빛 손은 네가 줄 사람을 세상에 더 많이 주었다.' WHERE entry = 2787;
UPDATE locales_page_text SET Text_loc1 = '아버지와 아들은 실리더스에있는 곤충 떼의 떠오르는 조류를 포함하기 위해 열렬히 싸웠다. 안퀴라즈 요새에서 겉으로보기에는 끝없이 이어져있는 규산염 덩어리가 침입 한 퀴라지 군대의 계급을 계속 강화했습니다. 실리더스 전체가 포위 당했다.' WHERE entry = 2795;
UPDATE locales_page_text SET Text_loc1 = '드래곤들은 세계가 또 하나의 커다란 대 재난을 겪지 않도록 신속하게 대응해야한다는 것을 알고있었습니다. 신중한 심의를 거친 후 최선의 행동 방침은 주둔군 또는 그 근원을 막는 것임이 결정되었다.' WHERE entry = 2805;
UPDATE locales_page_text SET Text_loc1 = '나이트 엘프와 드래곤 플라이의 본질에서 비롯된 커다란 장벽이 생겨날 것입니다. 안 시라 즈 벽 안에 실리 시드와 그 대 군주를 포함 할 수 있고 미래의 침입을 막을 수있는 마법의 장벽. 안퀴라즈는 그 자체로 감옥이 될 것입니다.' WHERE entry = 2806;
UPDATE locales_page_text SET Text_loc1 = '심연 기사단$B$B 초보자에게는 일상 의식을 위해 심연 기사단과 연락 할 수 있습니다. 연기 마법을 사용하지 않으려면 바람 돌을 사용할 때 항상 적절한 복장을 착용해야합니다.$B$B감독자가없는 예기치 않은 비상 사태가 발생하면 심연 기사단 소환 권한이 부여됩니다.$B$B 소환 의식에 대한 자세한 내용은 관련된 지난 달의 참 믿는자를 참조하십시오.' WHERE entry = 2813;
UPDATE locales_page_text SET Text_loc1 = '신앙. 신앙은 근심의 기쁨이 우리를 비춰주는 샘입니다. 가장 추운 실리더스의 밤에는 신앙이 우리를 따뜻하게 해줄 것입니다. 종말이 왔을 때 믿음은 우리 주님의 좋은 은혜를 지켜줄 것입니다.$B$B 파이스는 우리를 구원 할 것입니다.' WHERE entry = 2821;
UPDATE locales_page_text SET Text_loc1 = '놀랄 만한! 우리는 약간의 성공을 거두었지만, 우리가 추출 할 수 있었던 마법의 양은 아주 적었습니다. 이 유망한 새로운 접근법에 초점을 맞추기 위해 대부분의 견습생을 학업에서 제외시킬 것입니다.$B$B 운에 따라, 우리는 그 과정을 다듬고 한 돌로 두 마리의 새를 죽일 수 있어야합니다 - 풍부한 원천 우리 자신을위한 에너지, 그리고 우리가 앞으로 만날지도 모르는 모든 지옥 마법에 맞설 방법!' WHERE entry = 2850;
UPDATE locales_page_text SET Text_loc1 = '모든 건강한 남성과 여성에게:\n\n 스컬지가 돌아왔고 우리는 이 위협에 맞서기 위해 말다툼을 제쳐두어야 합니다.  은빛 여명회는 스컬지의 위협에 맞서 무기를 들고자 하는 그 누구도 외면하지 않을 것입니다.\n\n 우리 땅을 지키려는 자들이 동부 역병지대에 있는 희망의 빛 예배당에 집결하고 있습니다.  함께라면 우리는 승리할 것입니다.\n\n 롤스의 수호자\n 은빛 새벽' WHERE entry = 2872;
UPDATE locales_page_text SET Text_loc1 = '&lt;페이지마다 고대 엘프의 룬문자가 가득합니다.&gt;<br /><br />본 서적은 하급 영약을 제조하는 데 필요한 재료를 수집하고 제작하는 과정에서 일어난 사건들에 대한 기억을 담고 있다.<br /><br />부디 이 책이 적들의 손에 들어가지 않기를.<br /><br />부디 살아서 다시 한번 쿠엘탈라스에 창백한 달빛이 비치는 광경을 볼 수 있기를.<br /><br />부디 캘타스님의 은총 속에서 숨을 거두기를.<br /><br />부디 일리단님의 영광을 위해 살생도 불사하기를.<br /><br />-텔미우스 드림시커$B<img src=\\$B />$B<img src=\\$B />$B<img src=\\$B />$B<img src=\\$B />' WHERE entry = 1634;
UPDATE locales_page_text SET Text_loc1 = '이 고대 조각의 토기가 울다 만 굴착에서 회수되었습니다. 비록 그들이 암시적인 룬 문자 또는 상형 문자의 길을 거의 잡지 못하고 있지만, 그들은 고대의 드워프 종족의 장인 정신과 나날의 액세서리를 말하고 있습니다.' WHERE entry = 1758;
UPDATE locales_page_text SET Text_loc1 = '2 차 대전의 화재로 사망 한 얼라이언스는 오크의 위협을 막기위한 공격적인 조치를 취했습니다. 포로어 오크를 수용하기위한 다수의 대규모 수용소가 로데론 남부에 건설되었습니다. 성기사들과 베테랑 얼라이언스 병사들을 지키고 캠프가 큰 성공을 거두었습니다.' WHERE entry = 1992;
UPDATE locales_page_text SET Text_loc1 = '제시 모랄레스의 사랑의 기억' WHERE entry = 2217;
UPDATE locales_page_text SET Text_loc1 = '우리 처음 주간은 갔다. 그리고 사람은 처음 주간을 갈 것을 예상 할 수있다. 우리 시대의 대부분은베이스 캠프를 수립하는 데 필요한 준비를하는 데 몰두했습니다. 나는 담수 강 입구에 의해 이상적인 설정을했다. 근처에 버려진 부두가있는 것으로 판단하여이 지역은 언젠가 거주하게되었습니다. 원래의 거주자에 관해서는 시간 만이 그 이야기를 말할 수 있습니다.' WHERE entry = 2946;
UPDATE locales_page_text SET Text_loc1 = '그 살해는 탐험대들 사이에서 축제 분위기를 불러 일으켰습니다. 바닐은 모두가 즐길 수있는 미드를 쏟아 부었다. 그러나 우리의 축제는 오래 가지 못했습니다. 우리가 기지 캠프로 돌아가는 수송을 위해 시체를 준비 할 때 우리는 모두 끔찍한 으르렁 거리에 의해 경계를당했습니다. 내 년 동안 나는 피가 흐트러지기 때문에 아무것도 듣지 못했습니다.' WHERE entry = 2955;
UPDATE locales_page_text SET Text_loc1 = '나는 그 모피가 아제로스 전역에 높은 수요가 있기 때문에 다음날 사냥 표범을 보낼 탐험을 약속했다. 동맹의 이름으로 용맹스럽게 목숨을 바칠 수있는 유능한 사냥꾼, 덫 사냥꾼 및 모피 무역상들 모두와 함께 그러한 요구가 존재해야한다는 것은 의미가 있습니다.' WHERE entry = 2957;
UPDATE locales_page_text SET Text_loc1 = '나는 해안선이 랩터들로부터 피난처가되기를 희망하면서, 파티를 바다쪽으로 이끌었다. 서두르지도 않고 너무 북쪽으로, 너무 높은 고도로 이동했습니다. 실수가있었습니다. 그 잘못은 내 것이 었습니다. 우리는 깎아 지른듯한 절벽에 그만 두었습니다. 랩터스는 몇 발자국 뒤에 있습니다.' WHERE entry = 2970;
UPDATE locales_page_text SET Text_loc1 = '그리고 기적적인 일이 일어났습니다. 떨어져서 우리 쪽에서 우리는 굉장히 하얀 타이거의 별개의 그리고 무서운 포효를 들었다. 그들의 수에도 불구하고, 맹금류는 돌고 모든 방향에서 뿌렸다.우리는 호랑이가 우리를 지나서 뛰쳐 나와 랩터 중 한 명을 놀라게하면서 짧은 플래시를 보았습니다. 명령을 줄 필요가 없습니다. 우리 당원 모두 네가 도망 갈 시간임을 알았다.' WHERE entry = 2973;
UPDATE locales_page_text SET Text_loc1 = '</BR><BR/><BR/><BR/><BR/></BR></BR></BR></BR><P align = \"center\"></BR></BR></BR></BR></BR></BR></BR></BR></BR><H1 align = \"center\"> 엘리자 </H1> > 사랑하는 아내, 지구가 당신의 굶주림을 시들게 해줍니다. </P></BODY></HTML>' WHERE entry = 750;
UPDATE locales_page_text SET Text_loc1 = '달라 란 마법사가 빛의 양심을 다하여 늑골을 찾으려하지 않는다는 것은 나의 희망입니다. 어떤 협정도 당할 수 없기 때문에 어떤 비밀도 배울 수 없으며,이 짐승들로부터 오는 선한 것이 오지 않을 것입니다. 우리 안에서 발견되고 파괴되지 않는다면, 우리의 위험은 무서울 것입니다 ...' WHERE entry = 705;
UPDATE locales_page_text SET Text_loc1 = '블리딩 스패로우호: 적하 물품 및 승객 목록<br /><br />럼주 20통. 목적지: 테라모어<br />밀가루 50포대. 목적지: 테라모어<br />여러 가지 노움 공구 2상자. 목적지: 톱니항<br />면직물 30필. 목적지: 테라모어<br />양념 4상자. 목적지: 테라모어<br />승객 3명. 목적지: 테라모어$B선장,<br />여행에 행운이 함께하길 바랍니다. 안타깝게도, 우리의 첫 유괴 시도에는 행운이 따라 주지 않았습니다. 우리들이 스톰윈드와 아이언포지 동굴에서 목표물과 마주대한 그것이 유인용 미끼임을 알게 되었습니다. 그는 우리가 생각했던 것보다 더 영리한 자였던 것 같습니다.<br />하지만 두 번째 계획이 이미 실행 중입니다. 데피아즈 첩보원들은 목표물이 테라모어에 접근할 때 중간에 붙잡아 올 만반의 준비가 되어 있습니다. 곧 스톰윈드는 우리로 인해 뼈아픈 고통을 맛보게 될 것입니다.<br />- M' WHERE entry = 527;
UPDATE locales_page_text SET Text_loc1 = '당신은 사랑과 선행으로 조용한 삶을 살았습니다.   가난한 이들에게 베풀고, 병든 이들을 치료하고, 죽어가는 이들을 위로했습니다.   당신은 영원한 평화의 내세가 주어질 것이라는 믿음으로 안심하고 기쁨으로 기다렸지만 배신당했습니다.$B$배신은 당신에게 위로를 줄 수 없습니다.   반면에 복수는 내 힘으로 할 수 있다.   데스넬의 오래된 교회로 오면, 네가 배운 바로 그 신앙으로 치명적인 피해를 입히는 방법을 가르쳐주마.$B$B -사제 조련사 암흑 성직자 듀에스텐.' WHERE entry = 692;
UPDATE locales_page_text SET Text_loc1 = '발레아 쌍검$b주홍 성전의 전사$b알터락의 시민$b동부 역병의 땅 깊은 곳에서 마지막으로 목격되었습니다.' WHERE entry = 2177;
UPDATE locales_page_text SET Text_loc1 = '당신의 새로운 지하 세계를 만끽하고, 당신의 힘을 휘둘러 우리를 박멸하려는 자들의 세계를 정화하세요.   우리의 적은 군단이지만, 우리는 불꽃과 그림자로 그들을 파괴할 것이다.$B$B너에게 어둠과 소환의 방법을 가르칠 준비가 되면 오래된 데스넬 교회에서 나를 찾을 수 있을 것이다.$B$B -맥시밀리언, 워록 트레이너.' WHERE entry = 693;
UPDATE locales_page_text SET Text_loc1 = '이 글을 읽고 있다면, 당신은 지하세계의 시련에서 살아남아 포세이큰의 대열에 합류하기 위해 우리에게 돌아온 것입니다.   이 새로운 삶은 많은 이들에게 축복보다는 저주로 여겨지지만, 마음대로 하세요.$B$B비술의 길에서 더 많은 수련을 할 준비가 되었다면, 제가 알려드리겠습니다.  데스넬의 오래된 교회에서 저를 만나실 수 있습니다.$B$B -마법사 조련사 이사벨라.' WHERE entry = 691;
UPDATE locales_page_text SET Text_loc1 = '뼈를 깎고 일어나 지하실에서 나와야 할 일이 있습니다!   스칼렛 십자군은 우리 동족을 향해 재빠르게 움직이고, 다른 인간들은 틈만 나면 우리를 죽이고 있습니다.   네 검이 필요해. $B$B무기를 더 배우고 싶으면 데스넬의 폐허가 된 선술집으로 날 찾아와.   내가 가르쳐주마.$B$B -전사 조련사 다날 스턴.' WHERE entry = 694;
UPDATE locales_page_text SET Text_loc1 = '의식 완료$B$B원 테두리에 있는 마법 룬으로 진행 상황을 추적할 수 있습니다.  9개의 룬이 나타나면 의식이 완료된 것이며, 새로 강화된 서클에서 에너지가 솟아오르는 것을 볼 수 있습니다.$B$B거기에서 소로스의 문양을 불러내어 소로스로 통로를 열고 공포의 말을 끌어당길 수 있습니다.$B$B드레드스티드를 쓰러뜨리고 영혼을 풀어주세요.  정령과 대면하면 정령이 매혹되며, 소환의 비밀을 보상으로 받을 수 있습니다.' WHERE entry = 2711;
UPDATE locales_page_text SET Text_loc1 = '  헤멧 네싱와리의 그린 힐즈 오브 스트랭글 쏜$b$b' WHERE entry = 124;
UPDATE locales_page_text SET Text_loc1 = '달라 란 마법사가 빛의 양심을 다하여 늑골을 찾으려하지 않는다는 것은 나의 희망입니다. 어떤 협정도 당할 수 없기 때문에 어떤 비밀도 배울 수 없으며,이 짐승들로부터 오는 선한 것이 오지 않을 것입니다. 우리 안에서 발견되고 파괴되지 않는다면, 우리의 위험은 무서울 것입니다 ...' WHERE entry = 710;
UPDATE locales_page_text SET Text_loc1 = '이 설명서의 페이지를 채우는 소용돌이 치는 기호와 그림은 이해할 수 없을 정도로 난해합니다.' WHERE entry = 910;
UPDATE locales_page_text SET Text_loc1 = '비취 해. 그들은 많은 다른 장소에 숨어 있습니다. 그것들은 드뭅니다. 그러나 대장장이 나 기술자와 이야기 할 때 하나 또는 두 개의 여유가있을 수 있습니다.' WHERE entry = 930;
UPDATE locales_page_text SET Text_loc1 = '이 증명서를 소지 한 사람은 일급 성직자와 도둑이받을 자격이 있다고 존중하고 존중할 자격이 있습니다.' WHERE entry = 1010;
UPDATE locales_page_text SET Text_loc1 = '이 데이터의 보안 등급이 너무 높아서 설명하기 위해 새로운 번호가 발명되기까지 기다리고 있습니다!' WHERE entry = 1210;
UPDATE locales_page_text SET Text_loc1 = '이 장부를 찾은 다음,이 장부와 함께이 품목들을 모두 찾아 가제트로 돌아가십시오. 그러면 나는 당신에게 보상 할 것입니다.' WHERE entry = 1590;
UPDATE locales_page_text SET Text_loc1 = '이 3 페이지 문서는 비어 있습니다.' WHERE entry = 2550;
UPDATE locales_page_text SET Text_loc1 = '부적에는 5 개의 보석이 없습니다. 그리고 그 보석들이 발견되어 상징으로 다시 자리 잡으면 그 힘은 현재의 형태보다 훨씬 커질 것입니다. 나는 5 개의 보석을 발견했지만, 그것을 수집하는 데 도움이 될 당신의 기술 중 하나가 필요합니다.살해 무명의 선지자는 그의 이단을 훔치는 것과 마찬가지로 확실한 이단이며, 내가 다음에 너에게 물어 보는 것은 켄타 우르가 그것을 생각조차하지 않을 것이라고 비난 할 것이다.' WHERE entry = 2594;
UPDATE locales_page_text SET Text_loc1 = '월드 오브 워크래프트에 오신 것을 환영합니다!$B$B세상은 우리에게 무서운 곳이지만 여전히 전투의하러에서 승리 할만큼 강력합니다 ... 우리는 그 성가신 얼라이언스를 죽이기 위해 무엇이 필요합니다 우리는 무당이 만들어졌습니다!$B$B' WHERE entry = 2601;
UPDATE locales_page_text SET Text_loc1 = '영의 부적의 힘을 사용하여 그 (것)들에게서 명예와 주옥을 가지고 가도록 강요하십시오! 후에 보석을 영혼 부적에 넣고 돌려 보내십시오. 내가 부적 부적을 얻은 후에 나는 종족을 개혁 할 수있을만큼 충분히 강해 져서 마침내 조상들이 우리가되기를 원했던 것처럼 될 수 있습니다!' WHERE entry = 2610;
UPDATE locales_page_text SET Text_loc1 = '여기에 재가있다. 이것들은 나의 온전함, 나의 열정, 그리고 나의 운전의 재이다. 모두, 완전히 파괴되었습니다. 이 황량한 지옥의 땅을 바라 보는 모든 사람들이이 타락한 종을 기억하기를 바랍니다. 그는 동맹군에게 피를 흘렸고, 호드를 희생 시켰습니다. 그는 자신이 가장 소중하게 여긴 것을 사냥했던 사악하고 영혼없는 사람들에게 완전히 화를 냈습니다. 그들이 그들의 수고로 잔치를 베풀 때, 그들은 진노를 겪을 수 있습니다. 어쩌면이 세상에서가 아니라, 이후 모든 세상에서. 내 선언, 내 맹세, 내 영원한 약속입니다.나는 고통을 복수 할 것이다.' WHERE entry = 2905;
UPDATE locales_page_text SET Text_loc1 = '나는 비명을 지르고 싶었지만 단지 헐떡거리는 낮은 소리만이 내 입술 밖으로 새어 나왔을 뿐이다. 나의 이런 반항적인 행동은 즉시 폭력으로 다스려졌다. 바닥에 쓰러져 있을 때 나는 사루안의 시체 앞을 걸어다니는 마티스의 모습을 볼 수 있었다. 그는 분명 걱정이 있어 보였다. 그는 만약 사루안이 구타 때문에 죽은 것이면 시로나스인지 시로나인지 하는 자가 자기를 뼈만 남도록 벌을 줄 거라고 했다.' WHERE entry = 2939;
UPDATE locales_page_text SET Text_loc1 = '마커스는 두려움과 분노가 섞여서 그녀를 향해 섰습니다. \"보상은 협상 할 수 없다!\" 그는 자신의 신경을 모으는 동안 잠시 멈추고 자신의 작은 모양에 맞 섰다. 그들의 입술은 뜨겁게 만났고 서리 갑옷이 뜨거운 물에 잠겼습니다.$B$B \"이 퀘스트에 또 다른 단계가 있습니까?\" 그녀는 놀랐고 흥분으로 눈부 셨다.$B$B <그림을 앞으로 나아 가지 않으면 서 수백 페이지가 넘는다.>' WHERE entry = 2987;
UPDATE locales_page_text SET Text_loc1 = '느슨하게 번역 된 버전 ... </P><BR/><P> 태양의 빛에 비추어 볼 때, </P><P/>></P><P> 피의 자녀들, </P><P> 빛에 의해, </P><P></P><P> 피를 흘린 어린이들. </P><P> 실패한 아이들 혈액 속의 어린이들 </P><P> 태양의 빛에 의해 </P><P> 태양. </P></BODY></HTML>' WHERE entry = 2991;
UPDATE locales_page_text SET Text_loc1 = '모든 일에서 성기사들은 우리의 힘을 보충하는 빛을 반사해야합니다. 우리 종류의 신성을 위해 노력하는 것이 우리가 신을 위해 노력한다는 것을 의미하지는 않습니다. 우리는 모든 행동을 잘하기 위해 노력합니다.' WHERE entry = 2994;
UPDATE locales_page_text SET Text_loc1 = '<이 심하게 태운 페이지에는 인식 할 수없는 단어가 없습니다.>' WHERE entry = 3001;
UPDATE locales_page_text SET Text_loc1 = '에버그로브에서 출발 한 이후로 나는 까마귀 책에 대한 공부를 계속했고, 까마귀 하나님을 물리 칠 수있는 정보를 발견했습니다.$B$B 영혼을 기쁘게 해드릴 수 있기 때문에 기대해 봅니다. 그들은 까마귀 신과의 싸움에서 자유롭게 그들의 도움을 제공 할 것입니다.$B$B 처음에 영혼을 풀어 주었을 때, 그들은 수세기 동안 잠들었을 것입니다. 시간이 지남에 따라 치유 된 주문을 사용하면 에너지를 불어 넣어 생명을 불어 넣어 전투에서 도움을 얻을 수 있습니다. 마술이 사라지면 그들은 잠에서 깨어날 것입니다.$B$B 다음은 각 새의 정신에 관한 내 노트 모음입니다.' WHERE entry = 3002;
UPDATE locales_page_text SET Text_loc1 = '절망하지 마십시오. 당신의 특별한 귀신이 어딘가에 있어요.' WHERE entry = 3007;
UPDATE locales_page_text SET Text_loc1 = '당신의 칼과 당신의 망치와 당신의 랜스를 올려라. 크리스털은 우리에게 평화를 누릴 기회가 있다고 말했습니다.' WHERE entry = 3008;
UPDATE locales_page_text SET Text_loc1 = '맥주가 가득한 머리로 두려워 할 필요가 없습니다!' WHERE entry = 3009;
UPDATE locales_page_text SET Text_loc1 = '한명 보단 두명이 낫다! 그렇다면 항상 친구가있을 것입니다.' WHERE entry = 3010;
UPDATE locales_page_text SET Text_loc1 = '지혜는 여러 형태로 나오지만 항상 결정체에서 흘러 나옵니다.' WHERE entry = 3011;
UPDATE locales_page_text SET Text_loc1 = '긍정적 인 생각! 하나에 큰 창자는 다른 한 쌍의 사랑 핸들입니다.' WHERE entry = 3012;
UPDATE locales_page_text SET Text_loc1 = '내일 특별한 사람을 만날 것입니다. 그래서 기억하십시오 : 친구를 사귈 때 친절을 베풀면서 더 많은 친구들을 사로 잡습니다.' WHERE entry = 3013;
UPDATE locales_page_text SET Text_loc1 = '춤에 대한 당신의 성향은 모든 사람의 얼굴에 미소를 가져옵니다.' WHERE entry = 3015;
UPDATE locales_page_text SET Text_loc1 = '친구, 친척, 동료, 임의의 낯선 사람 또는 양심이 당신에게 말할 수있는 것은 상관없이 당신은 특별합니다.' WHERE entry = 3016;
UPDATE locales_page_text SET Text_loc1 = '다른 모든 것이 실패하면, 보석금을받을 시간입니다.' WHERE entry = 3017;
UPDATE locales_page_text SET Text_loc1 = '술 취함은 경건에 가깝다.' WHERE entry = 3018;
UPDATE locales_page_text SET Text_loc1 = '경고 : 곱창은 사람이 섭취하는 데 안전하지 않았습니다.' WHERE entry = 3019;
UPDATE locales_page_text SET Text_loc1 = '당신은 하늘의 위대한 금속 손으로 선택되었습니다! 이제 일하러 가자.' WHERE entry = 3020;
UPDATE locales_page_text SET Text_loc1 = '삶의 의미는 ... (이 메시지의 나머지 부분은 실수로 먹었습니다.)' WHERE entry = 3023;
UPDATE locales_page_text SET Text_loc1 = '죄송합니다. 이번엔 승자가 아닙니다. 다시 놀아주세요.' WHERE entry = 3024;
UPDATE locales_page_text SET Text_loc1 = '오늘 적을 만들어 즉시 죽일거야.' WHERE entry = 3025;
UPDATE locales_page_text SET Text_loc1 = '인생에서 더 높은 길을 찾으십시오. 그렇게하면 낮은 생명을 피할 수 있습니다.' WHERE entry = 3027;
UPDATE locales_page_text SET Text_loc1 = '아이들 : 조엘과지나. 부인 : 수잔나' WHERE entry = 3037;
UPDATE locales_page_text SET Text_loc1 = '우리의 모든 수고가이 순간에 맞춰 이루어졌습니다. 우리 주인공들은 아제로스를 찢어 버릴 영광스러운 싸움에서 서로를 대적 할 것입니다.$B$B 우리는 마지막 시간에 살고 있습니다, 형제들. 당신의 임무를 잡아라.노력하십시오. 우리는 곧 승리 할 것입니다!$B$B' WHERE entry = 3072;
UPDATE locales_page_text SET Text_loc1 = '<이 심하게 태운 페이지에는 인식 할 수없는 단어가 없습니다.>' WHERE entry = 3076;

